# -*- coding: utf-8 -*-
# Dados corrigidos das 252 licoes (Problema A). Gerado automaticamente.

DADOS = [
    ("Criacao e Patriarcas", 1, "A Obra da Criação", "No início Deus criou os céus e a terra. Em seis dias criou tudo: luz, firmamento, mares, vegetação, luminares, animais e o ser humano à Sua imagem. No sétimo dia descansou.", "Genesis 1:1-2:3", "Compreender a ordem e propósito da criação divina", "Deus criou o universo em seis dias por Sua palavra, culminando com a humanidade. O sétimo dia estabelece o padrão de descanso."),
    ("Criacao e Patriarcas", 2, "A Queda e Suas Consequências", "Deus colocou Adão e Eva no Éden com liberdade para comer de todas as árvores, exceto a árvore do conhecimento do bem e do mal. A serpente enganou Eva, que comeu e deu a Adão.", "Genesis 3:1-24", "Entender o pecado original e suas consequências", "A desobediência trouxe a morte espiritual, a separação de Deus e a expulsão do Éden. Deus prometeu uma semente que esmagaria a cabeça da serpente."),
    ("Criacao e Patriarcas", 3, "Caim e Abel", "Abel ofereceu ao Senhor as primícias do seu rebanho, mas Caim dos frutos da terra. O Senhor aceitou Abel, mas não a Caim. Caim, dominado pela inveja, matou seu irmão.", "Genesis 4:1-16", "Compreender a primícia do sacrifício e o perigo do pecado", "O primeiro assassinato da Bíblia demonstra como o pecado se perpetua. Deus marcou Caim, mostrando misericórdia mesmo na desobediência."),
    ("Criacao e Patriarcas", 4, "A Arca de Noé", "Deus viu a maldade humana e decidiu destruir a terra com dilúvio, mas achou graça em Noé. Noé construiu a arca conforme as instruções, levando sua família e pares de animais.", "Genesis 6:1-9:17", "Reconhecer o juízo divino e a fidelidade de Deus", "Noé obedeceu em tudo. Depois do dilúvio, Deus fez aliança com um arco‑íris como sinal."),
    ("Criacao e Patriarcas", 5, "A Chamada de Abraão", "Deus disse a Abraão: \"Vai-te da tua terra e vai para a terra que eu te mostrarei.\" Prometeu fazer dele grande nação e que nele seriam abençoadas todas as famílias da terra.", "Genesis 12:1-9", "Entender a aliança de Deus com Abraão", "A chamada de Abraão inicia a história da redenção. Sua obediência, apesar da incerteza, é modelo de fé."),
    ("Criacao e Patriarcas", 6, "A Prova de Isaque", "Deus ordenou a Abraão que oferecesse Isaac em sacrifício no monte Moriá. No momento final um anjo deteve sua mão e um cordeiro foi oferecido em substituição.", "Genesis 22:1-19", "Reconhecer o exemplo de obediência e fé de Abraão", "A prova do Moriá e tipologia do sacrifício de Cristo. Deus proveu o cordeiro como substituto."),
    ("Criacao e Patriarcas", 7, "Jacó e Esaú", "Isaac teve gêmeos: Esaú, o primogênito, e Jacó. Esaú vendeu o direito de primogenitura por um prato de lentilhas. Depois Jacó recebeu a bênção do primogênito.", "Genesis 25:19-34; 27:1-40", "Compreender as consequências do engano e busca por vantagem", "A rivalidade entre Jacó e Esaú demonstra as consequências da preferência humana e do engano."),
    ("Criacao e Patriarcas", 8, "O Escaldo de Jacó em Peniel", "Jacó lutou toda a noite com um anjo no vale do Jaboque e foi vitorioso, embora tivesse o quadril deslocado. Recebeu o nome de Israel.", "Genesis 32:22-32", "Entender a transformação de Jacó", "Jacó partiu como enganador e voltou como Israel, aquele que foi tocado por Deus e mudado."),
    ("Criacao e Patriarcas", 9, "José e os Sonhos", "José, filho favorito de Jacó, recebeu sonhos de grandeza que provocaram inveja dos irmãos. Eles o venderam como escravo. No Egito, José foi preso mas interpretou sonhos do faraó.", "Genesis 37:1-41:41", "Compreender o propósito de Deus nas adversidades", "A história de José demonstra como Deus transforma o mal em bem para salvar muitas vidas."),
    ("Criacao e Patriarcas", 10, "José Perdoa seus Irmãos", "José revelou sua identidade: \"Vós pensastes mal contra mim, mas Deus o encaminhou para o bem.\" José chorou e abraçou seus irmãos.", "Genesis 42:1-45:15", "Reconhecer o poder do perdão e a soberania de Deus", "O perdão de José é um dos mais belos exemplos na Bíblia. Ele reconheceu a mão de Deus em tudo."),
    ("Criacao e Patriarcas", 11, "A Descida ao Egito", "Jacó e toda a sua família desceram ao Egito, reunindo‑se a José. Foram 70 pessoas. Israel estabeleceu‑se na terra de Gosen.", "Genesis 46:1-47:12", "Entender como a descendência de Abraão se multiplicou", "A descida ao Egito cumpriu a profecia de que sua descendência seria estrangeira por 400 anos."),
    ("Criacao e Patriarcas", 12, "José interpreta sonhos do faraó", "O faraó sonhou com sete vacas gordas devoradas por sete magras, e sete espigas cheias devoradas por sete magras. José interpretou: sete anos de abundância seguidos de sete anos de fome.", "Genesis 41:1-36", "Entender como Deus usa sonhos para revelar seus planos", "José revelou que apenas a sapiência divina pode interpretar sonhos e preparar o povo para o futuro."),
    ("Exodo e a Lei", 1, "O Nascimento de Moisés", "Moisés nasceu em tempos em que o faraó matava bebês hebreus. Sua mãe o colocou num cesto no Nilo. A filha do faraó o encontrou e criou‑o no palácio.", "Exodo 2:1-10", "Entender como Deus prepara seus libertadores", "Deus protegeu Moisés desde o nascimento, preparando‑o para liderar Israel. O Nilo, fonte de morte, tornou‑se caminho de vida."),
    ("Exodo e a Lei", 2, "As Dez Pragas do Egito", "Deus enviou dez pragas sobre o Egito para libertar Israel: água em sangue, rãs, mosquitos, moscas, peste, furúnculos, granizo, gafanhotos, trevas e morte dos primogênitos.", "Exodo 7:1-12:32", "Reconhecer o poder de Deus sobre os deuses do Egito", "Cada praga atingiu um deus egípcio, demonstrando a supremacia do Deus de Israel."),
    ("Exodo e a Lei", 3, "A Passagem do Mar Vermelho", "Israel cruzou o Mar Vermelho em seco, com as águas erguidas como muralhas. Os egípcios que os perseguiram foram engolidos pelas águas. Moisés e Miriam cantam de louvor.", "Exodo 14:1-15:21", "Entender a salvação de Deus e o louvor que se segue", "O Mar Vermelho é o maior ato de salvação do AT, tipo do batismo e da libertação do pecado."),
    ("Exodo e a Lei", 4, "Os Dez Mandamentos", "No monte Sinai, Deus deu a Lei a Moisés: não ter outros deuses, não fazer imagens, não usar o nome em vão, lembrar o sábado, honrar pais, não matar, não adulterar, não furtar, não mentir, não cobiçar.", "Exodo 20:1-17", "Conhecer os mandamentos como base da aliança", "Os Dez Mandamentos são o núcleo da Lei, revelando a vontade de Deus para a vida humana."),
    ("Exodo e a Lei", 5, "O Bezerro de Ouro", "Enquanto Moisés estava no Sinai, o povo fez um bezerro de ouro para adorar. Moisés, ao descer, quebrou as tábuas da Lei e julgou os idólatras. Depois subiu de novo e recebeu novas tábuas.", "Exodo 32:1-35", "Reconhecer o perigo da idolatria e a paciência de Deus", "O bezerro demonstra a tendência humana de buscar substitutos tangíveis para o Deus invisível."),
    ("Exodo e a Lei", 6, "O Tabernáculo", "Deus instruiu Moisés a construir o tabernáculo, lugar onde Sua presença habitaria entre o povo. Tinha o pátio, o santuário e o Santo dos Santos, onde ficava a Arca da Aliança.", "Exodo 25-27; 40", "Entender a importância da presença de Deus no meio do povo", "O tabernáculo revela o desejo de Deus de habitar com Sua criatura e antecipa o templo e a encarnação."),
    ("Exodo e a Lei", 7, "O Sangue da Aliança", "Moisés aspergiu o povo com sangue de animais, dizendo: \"Este é o sangue da aliança.\" O sangue era sinal de compromisso entre Deus e Israel.", "Exodo 24:1-8", "Entender o significado do sangue na aliança", "O sangue da aliança é tipo do sangue de Cristo que estabelece a nova aliança."),
    ("Exodo e a Lei", 8, "Levítico: Santidade de Deus", "Levítico revela a santidade de Deus e as instruções para sacrifícios, pureza e festivais. \"Sede santos, porque eu sou santo.\"", "Levitico 11:44-45; 19:2", "Compreender o chamado a santidade", "Levítico ensina que a aproximação a Deus exige pureza e obediência, apontando para a santidade necessária na nova aliança."),
    ("Exodo e a Lei", 9, "O Dia da Expiação", "Uma vez por ano, o sumo sacerdote entrava no Santo dos Santos com sangue de um bode, para expiar os pecados de Israel. Dois bodes: um morto, outro vivo (scapegoat).", "Levitico 16", "Entender o simbolismo do Dia da Expiação", "O Dia da Expiação antecipa a obra expiatória de Cristo, o nosso sumo sacerdote que entrou no céu."),
    ("Davi: O Rei segundo o Coracao de Deus", 1, "A Unção de Davi", "Samuel ungiu Davi, o menor dos filhos de Jessé, como futuro rei de Israel. Enquanto Saul era rei, Deus já havia escolhido um homem segundo o Seu coração.", "1 Samuel 16:1-13", "Entender que Deus olha o coração, não a aparência", "Deus rejeitou os irmãos mais velhos de Davi e escolheu o menor, revelando que Sua escolha não depende de aparência."),
    ("Davi: O Rei segundo o Coracao de Deus", 2, "Davi e Golias", "O filisteu Golias, um gigante de quase 3 metros, desafiou Israel por 40 dias. Davi, um pastor jovem, aceitou o desafio com uma funda e cinco pedras, derrubando o gigante.", "1 Samuel 17:1-54", "Entender que a fé vence o impossível", "Davi venceu não pelo armamento, mas pela confiança em Deus. A funda e pedras simbolizam a simplicidade da fé."),
    ("Davi: O Rei segundo o Coracao de Deus", 3, "A Amizade de Davi e Jônatas", "Jônatas, filho do rei Saul, amou Davi como a si mesmo e fez aliança com ele. Quando Saul quis matar Davi, Jônatas o alertou e o protegeu.", "1 Samuel 18:1-4; 20:1-42", "Reconhecer o valor da amizade fiel", "A amizade Davi-Jônatas é um dos mais belos exemplos de lealdade na Bíblia, prefigurando o amor fraternal."),
    ("Davi: O Rei segundo o Coracao de Deus", 4, "O Pecado de Davi e Bate-Seba", "Davi viu Bate-Seba tomando banho, chamou-a e cometeu adultério. Para encobrir, mandou matar Urias, o marido. O profeta Natã o confrontou.", "2 Samuel 11:1-27", "Reconhecer que mesmo os mais fiéis podem cair", "O pecado de Davi demonstra que ninguém está acima da tentação. A consequência foi severa, mas a misericórdia de Deus prevaleceu."),
    ("Davi: O Rei segundo o Coracao de Deus", 5, "O Salmo 51: Arrependimento", "Davi orou: \"Tem misericórdia de mim, ó Deus, segundo a Tua benignidade... Cria em mim, ó Deus, um coração puro.\" Este salmo é o maior texto de arrependimento da Bíblia.", "Salmo 51:1-19", "Aprender a orar de arrependimento", "O Salmo 51 é o modelo bíblico de confissão, arrependimento e busca por restauração com Deus."),
    ("Davi: O Rei segundo o Coracao de Deus", 6, "Salmo 23: O Pastor", "\"O Senhor é meu pastor, nada me faltará.\" Davi, que era pastor antes de ser rei, usou a imagem do pastor para descrever o cuidado de Deus.", "Salmo 23", "Entender o cuidado pessoal de Deus", "Salmo 23 e o mais conhecido salmo, revelando que Deus guia, provê, protege e restaura Seu povo."),
    ("Davi: O Rei segundo o Coracao de Deus", 7, "Salmo 119: Amor à Palavra", "O maior salmo (176 versículos) e um acróstico sobre o amor à Lei de Deus. Cada versículo começa com uma letra do alfabeto hebraico.", "Salmo 119:1-176", "Cultivar o amor pela Palavra de Deus", "Salmo 119 demonstra que a Palavra de Deus é luz, vida, alegria e esperança para o caminho."),
    ("Davi: O Rei segundo o Coracao de Deus", 8, "Salmo 22: Profecia da Cruz", "\"Meu Deus, meu Deus, por que me abandonaste?\" Davi profetizou o sofrimento do Messias, palavras que Jesus citou na cruz.", "Salmo 22:1-31", "Reconhecer as profecias messiânicas nos salmos", "Salmo 22 descreve com precisão a crucificação de Jesus, escrito milênios antes do evento."),
    ("Davi: O Rei segundo o Coracao de Deus", 9, "Salmo 139: Omnipresença de Deus", "\"Para onde fugirei do Teu espírito? Para onde irei da Tua presença?\" Davi reconhece que Deus o conhece completamente e está em todo lugar.", "Salmo 139:1-24", "Entender que Deus nos conhece e nos acompanha", "Deus sabe tudo sobre nós, antes mesmo de nascermos, e nunca nos deixa sozinhos."),
    ("Salmos: Oracao e Adoracao", 1, "Salmo 91 - Proteção Divina", "Aquele que habita no esconderijo do Altíssimo, descansará à sombra do Todo-Poderoso. Direi do Senhor: Ele é o meu refúgio e a minha fortaleza, o meu Deus, em quem confio.", "Salmo 91:1-16", "Confiar na proteção absoluta de Deus", "Salmo 91 e a declaração bíblica de proteção divina. Quem se refugia em Deus está guardado de pragas, armas e perigos."),
    ("Salmos: Oracao e Adoracao", 2, "Salmo 46 - Refúgio Inabalável", "Deus é o nosso refúgio e fortaleza, socorro sempre presente nas angústias. Por isso não temerei, ainda que a terra se mude e os montes se abalem no mar.", "Salmo 46:1-11", "Encontrar paz no meio do caos", "Salmo 46 ensina que, mesmo quando o mundo desmorona, Deus é nossa rocha imóvel. Basta parar e reconhecer que Ele é Deus."),
    ("Salmos: Oracao e Adoracao", 3, "Salmo 103 - Bondade de Deus", "Bendize, ó minha alma, ao Senhor, e não esqueças de nenhum dos seus benefícios. Ele perdoa todas as tuas enfermidades e coroa de benignidade.", "Salmo 103:1-22", "Cultivar a gratidão por tudo que Deus faz", "Salmo 103 enumera os benefícios de Deus: perdão, cura, resgate, amor, misericórdia e satisfação. É um hino de gratidão."),
    ("Salmos: Oracao e Adoracao", 4, "Salmo 27 - O Senhor é a Minha Luz", "O Senhor é a minha luz e a minha salvação; a quem temerei? O Senhor é a fortaleza da minha vida; de quem me assustarei?", "Salmo 27:1-14", "Buscar a presença de Deus acima de tudo", "Davi declara que, mesmo cercado de inimigos, sua única busca é habitar na casa do Senhor e contemplar a Sua beleza."),
    ("Salmos: Oracao e Adoracao", 5, "Salmo 121 - Guarda do Senhor", "Ergo os meus olhos para os montes; de onde me vem o socorro? O meu socorro vem do Senhor, que fez os céus e a terra. O Senhor te guardará de todo mal.", "Salmo 121:1-8", "Confiança na guarda permanente de Deus", "Salmo 121 é um dos gritos de peregrino: Deus não dorme, não cochila, e guarda a entrada e a saída do Seu povo."),
    ("Salmos: Oracao e Adoracao", 6, "Salmo 34 - Louvor Contínuo", "Bendirei ao Senhor em todo tempo; o seu louvor estará sempre na minha boca. Provei e vi que o Senhor é bom; bem-aventurado o homem que nele confia.", "Salmo 34:1-22", "Cultivar um estilo de vida de louvor", "Davi escreveu este salmo após fingir loucura diante de Abimeleque. Mostra que, mesmo em dificuldades, podemos louvar."),
    ("Salmos: Oracao e Adoracao", 7, "Salmo 150 - A Grande Adoração", "Louvai ao Senhor no seu santuário; louvai-o no firmamento do seu poder. Louvai-o com sons de trombeta, harpa, tamborim e dança.", "Salmo 150:1-6", "Expressar adoração com tudo que temos", "Salmo 150 e o grande encerramento do livro dos Salmos: tudo o que tem fôlego louve ao Senhor!"),
    ("Salmos: Oracao e Adoracao", 8, "Salmo 8 - Grandeza do Ser Humano", "Senhor, o Teu nome é em toda a terra! Como é glorioso o Teu nome sobre os céus! Pôs os Teus abismos abaixo do homem.", "Salmo 8:1-9", "Reconhecer a dignidade que Deus deu ao ser humano", "O salmo contempla a grandeza da criação e a honra que Deus deu ao homem, colocando tudo sob seus pés."),
    ("Salmos: Oracao e Adoracao", 9, "Salmo 16 - Alegria na Presença", "Conserva-me, ó Deus, porque em Ti confio. Ao Senhor disse: tu és o meu Senhor, o meu bem não está em outro. Alegria há na Tua presença.", "Salmo 16:1-11", "Encontrar verdadeira alegria somente em Deus", "Davi declara que o seu bem está em Deus, e que na Sua presença há plenitude de alegria e gozo eterno."),
    ("Salmos: Oracao e Adoracao", 10, "Salmo 42 - Anseio por Deus", "Como anseia a corça por águas correntes, assim a minha alma anseia por Ti, ó Deus. A minha alma tem sede de Deus.", "Salmo 42:1-11", "Cultivar sede e fome de Deus", "O salmista compara sua sede espiritual com a sede de uma corça. Mesmo em tempos difíceis, sua alma busca a Deus."),
    ("Profetas: Alertas e Esperanca", 1, "Isaías 53 - O Servo Sofredor", "Ele foi desprezado e rejeitado pelos homens, homem de doenças e habituado ao sofrimento. Foi traspassado pelas nossas transgressões, moído pelas nossas iniquidades. Pela sua chaga fomos sarados.", "Isaias 53:1-12", "Reconhecer Jesus como o Servo Sofredor profetizado", "Isaías 53 e a profecia mais clara sobre a morte expiatória de Jesus, escrita 700 anos antes da cruz."),
    ("Profetas: Alertas e Esperanca", 2, "Isaías 9 - O Príncipe da Paz", "Para nos nasceu uma criança, para nos foi dado um filho; e o principado estará sobre os seus ombros. Conselheiro maravilhoso, Deus fortíssimo, Pai eterno, Príncipe da Paz.", "Isaias 9:1-7", "Reconhecer Jesus como o Príncipe da Paz prometido", "Isaías profetizou a vinda de um governante perfeito cujo reinado seria de paz, justiça eterna."),
    ("Profetas: Alertas e Esperanca", 3, "Jeremias 29 - Planos de Bem", "Porque eu bem sei os pensamentos que tenho a vosso respeito, pensamentos de paz e não de mal, para vos dar o fim que esperais.", "Jeremias 29:11", "Confiança nos planos de Deus mesmo na dificuldade", "Deus falou ao povo exilado na Babilônia: mesmo longe de casa, Ele tinha planos de bem para restaurá‑los."),
    ("Profetas: Alertas e Esperanca", 4, "Jeremias 31 - A Nova Aliança", "Farei uma aliança nova com Israel. Porei a minha Lei no seu interior e a escreverei nos seus corações. Serei o seu Deus e eles serão o meu povo.", "Jeremias 31:31-34", "Entender o fundamento da nova aliança em Cristo", "A profecia da nova aliança revela que Deus colocaria Sua Lei no coração, não em tábuas de pedra."),
    ("Profetas: Alertas e Esperanca", 5, "Daniel 3 - Os Amigos no Forno", "Sadraque, Mesaque e Abed‑nego se recusaram a adorar a estátua de ouro de Nabucodonosor. Foram jogados no forno quente, mas Deus os livrou: nem o cheiro de fogo ficou neles.", "Daniel 3:1-30", "Coragem para se manter fiel mesmo sob ameaça", "Os três jovens preferiram morrer a trair sua fé. Deus os livrou do forno, provando que Ele é soberano."),
    ("Profetas: Alertas e Esperanca", 6, "Daniel 6 - Na Cova dos Leões", "Daniel continuava orando a Deus três vezes por dia, mesmo com proibição. Denunciado, foi jogado na cova dos leões, mas Deus enviou um anjo e fechou as bocas dos leões.", "Daniel 6:1-28", "Fidelidade na oração como prioridade", "Daniel não parou de orar mesmo sob ameaça de morte. Sua fé era tão firme que nem leões puderam contra ele."),
    ("Profetas: Alertas e Esperanca", 7, "Oseias 2 - Amor Infeliz restaurado", "Deus comparou Oseias com uma mulher infiel, Gomer, para ilustrar como Israel era infiel a Deus. Mesmo assim, Deus prometeu restaurar e amar novamente.", "Oseias 2:1-23", "Entender o amor incondicional de Deus", "A história de Oseias e Gomer é um retrato vivo do amor de Deus: fiel mesmo quando o povo trai."),
    ("Profetas: Alertas e Esperanca", 8, "Amos 5 - Justiça e Equidade", "Buscai ao Senhor e viverei; buscai justiça e ponham a equidade. Odeio e desprezo os vossos festivais; não aceitarei as vossas ofertas.", "Amos 5:4-24", "Compreender que Deus prioriza justiça sobre ritual", "Amos denunciou a religiosidade vazia: Deus quer justiça e equidade, não sacrifícios sem amor."),
    ("Profetas: Alertas e Esperanca", 9, "Mateus 6 - O Messias Pobre", "Jesus nasceu em manjedoura e cresceu em Nazaré, cidade humilde. Disse: \"A raposa tem tocas, e as aves do céu têm ninhos, mas o Filho do Homem não tem onde repousar a cabeça.\"", "Mateus 8:19-20; Lucas 2:7", "Reconhecer a humildade do Deus que veio ao mundo", "Jesus escolheu a pobreza para redimir os pobres. O Messias prometido veio sem ostentação, em humildade."),
    ("Profetas: Alertas e Esperanca", 10, "Joel 2 - O Dia do Senhor", "O dia do Senhor vem, dia de trevas e não de luz. Mas depois diz: \"Derramarei do Meu Espírito sobre toda carne; vossos filhos e vossas filhas profetizarão.\"", "Joel 2:1-32", "Preparar-se para o Dia do Senhor e receber o Espírito", "Joel profetizou o juízo e a restauração, e a promessa do derramamento do Espírito, cumprida em Atos 2."),
    ("Jesus: Vida e Ministerio", 1, "Mateus 1 - O Nascimento de Jesus", "A genealogia de Jesus, filho de Davi, filho de Abraão. Maria, noiva de José, concebeu pelo Espírito Santo. José, homem justo, a recebeu sem dúvidas.", "Mateus 1:1-25", "Compreender a origem divina e humana de Jesus", "Jesus veio da linhagem de Davi, cumprindo as profecias. Sua concepção foi miraculosa, pelo poder do Espírito Santo."),
    ("Jesus: Vida e Ministerio", 2, "Mateus 3 - O Batismo de Jesus", "João Batista batizou Jesus no Rio Jordão. Ao subir das águas, os céus se abriram e o Espírito desceu como pomba. Uma voz disse: \"Este é o Meu Filho amado.\"", "Mateus 3:13-17", "Entender o significado do batismo e da aprovação divina", "Jesus, sendo sem pecado, foi batizado para cumprir toda justiça e iniciar Seu ministério público."),
    ("Jesus: Vida e Ministerio", 3, "Mateus 4 - A Tentação no Deserto", "Jesus foi conduzido ao deserto pelo Espírito e foi tentado por Satanás por 40 dias. Resistiu a cada tentação com a Palavra de Deus: \"Está escrito.\"", "Mateus 4:1-11", "Aprender a resistir à tentação com a Palavra", "Jesus usou a Escritura para vencer cada tentação. O exemplo é modelo para todos os crentes."),
    ("Jesus: Vida e Ministerio", 4, "Mateus 5 - O Sermão do Monte", "Jesus sentou e ensinou: Bem-aventurados os pobres de espírito, os mansos, os que choram, os que têm fome e sede de justiça. Vós sois a luz do mundo.", "Mateus 5:1-48", "Assimilar os ensinamentos fundamentais de Jesus", "O Sermão do Monte e a constituição do Reino de Deus: valores inversos ao mundo, amor aos inimigos, perfeição."),
    ("Jesus: Vida e Ministerio", 5, "Mateus 9 - O Coração de Jesus", "Jesus viu as multidões e teve compaixão, porque estavam cansadas e dispersas como ovelhas sem pastor. Começou a curar doentes e perdoar pecados.", "Mateus 9:1-38", "Reconhecer a compaixão infinita de Jesus", "Jesus sentiu profunda compaixão e agiu: curou paralíticos, perdoou pecados e chamou pecadores."),
    ("Jesus: Vida e Ministerio", 6, "Mateus 13 - As Parábolas", "Jesus ensinou em parábolas: o Semeador, o Joio e o Trigo, o Grão de Mostarda, o Tesouro Escondido, a Pérola de grande valor e a Rede.", "Mateus 13:1-58", "Entender os ensinamentos de Jesus através de histórias", "As parábolas revelam mistérios do Reino de Deus: como a Palavra é semeada, cresce e traz frutos."),
    ("Jesus: Vida e Ministerio", 7, "Mateus 14 - Pão e Peixes", "Jesus alimentou 5 mil homens com cinco pães e dois peixes, multiplicando-os. Também caminhou sobre as águas e acalmou a tempestade.", "Mateus 14:13-33", "Confiar no poder de Jesus para suprir necessidades", "Jesus transformou o pouco em abundância, demonstrando ser Senhor da criação e provedor do povo."),
    ("Jesus: Vida e Ministerio", 8, "João 1 - O Verbo se Fez Carne", "No princípio era o Verbo, e o Verbo estava com Deus, e o Verbo era Deus. Tudo foi feito por Ele. E o Verbo se fez carne e habitou entre nós.", "João 1:1-18", "Entender a natureza divina e eterna de Jesus", "João apresenta Jesus como o Verbo eterno, pré-existente, criador de todas as coisas que veio habitar entre os homens."),
    ("Jesus: Vida e Ministerio", 9, "João 3 - Nascer de Novo", "Jesus disse a Nicodemos: \"É necessário nascer de novo para ver o Reino de Deus. Quem crê no Filho unigênito não perece, mas tem a vida eterna.\"", "João 3:1-36", "Compreender a necessidade do novo nascimento espiritual", "Jesus revelou que a salvação vem pelo nascimento espiritual e pela fé no Filho de Deus."),
    ("Jesus: Vida e Ministerio", 10, "João 4 - A Samaritana", "Jesus falou com uma mulher samaritana no poço de Jacó. Revelou que Ele é o Messias e que Deus busca adoradores em espírito e em verdade.", "João 4:1-42", "Entender que Jesus transcende barreiras sociais", "Jesus quebrou barreiras de gênero, religião e cultura ao falar com a samaritana, revelando que todos são bem‑vindos."),
    ("Jesus: Vida e Ministerio", 11, "João 15 - A Videira e os Ramos", "Eu sou a videira verdadeira, e o meu Pai é o lavrador. Permanecei em mim, e eu em vós. Sem mim nada podeis fazer.", "João 15:1-27", "Compreender a necessidade de permanecer em Cristo", "Jesus é a videira; nós somos os ramos. Só frutificamos quando estamos ligados a Ele."),
    ("Jesus: Vida e Ministerio", 12, "Marcos 8 - A Cura dos Cegos", "Jesus aplicou lama nos olhos de um cego de Betsaida e ele passou a ver. Depois, Jesus perguntou: \"Que vês?\" E o homem via tudo claramente.", "Marcos 8:22-26", "Reconhecer Jesus como o curador completo", "Jesus curou em etapas, mostrando que o milagre é gradual e que Ele cuida de cada detalhe da cura."),
    ("Atos: A Igreja em Expansao", 1, "Atos 1 - A Ascensão de Jesus", "Jesus ressuscitado apareceu aos discípulos por 40 dias, falando do Reino de Deus. Depois, diante deles, foi elevado ao céu. Dois anjos disseram: \"Esse Jesus, que foi elevado, voltará.\"", "Atos 1:1-11", "Entender a ascensão e a promessa do retorno", "A ascensão marca a conclusão da obra terrena de Jesus e a espera ativa pela volta d'Ele."),
    ("Atos: A Igreja em Expansao", 2, "Atos 2 - O Pentecostes", "No dia de Pentecostes, um som como vento forte encheu a casa. Línguas de fogo pousaram sobre cada um. Começaram a falar em outras línguas. Pedro pregou e 3 mil foram salvos.", "Atos 2:1-47", "Receber o poder do Espírito Santo", "O Pentecostes e o cumprimento da promessa de Jesus: o Espírito Santo habita nos crentes e dá poder para testemunhar."),
    ("Atos: A Igreja em Expansao", 3, "Atos 4 - Coragem na Perseguição", "Pedro e João foram presos por pregar a ressurreição. Mas não pararam. A igreja orou e o Espírito Santo os encheu de ousadia.", "Atos 4:1-31", "Ter coragem para testemunhar mesmo sob perseguição", "Os líderes da igreja enfrentaram ameaças e prisões, mas oraram por mais coragem e não por livramento."),
    ("Atos: A Igreja em Expansao", 4, "Atos 7 - O Martírio de Estêvão", "Estêvão, cheio do Espírito Santo, enfrentou o Sinédrio com um discurso ousado. Apedrejado, pediu: \"Senhor, não lhes imputes este pecado.\" Foi o primeiro mártir cristão.", "Atos 7:1-60", "Reconhecer o custo e a honra do testemunho fiel", "Estêvão viu os céus abertos e perdoou seus assassinos, imitando a Jesus. Sua morte espalhou o evangelho."),
    ("Atos: A Igreja em Expansao", 5, "Atos 9 - A Conversão de Saulo", "Saulo ia perseguindo cristãos quando uma luz do céu o derrubou. Jesus disse: \"Saulo, Saulo, por que me persegues?\" Saulo se converteu e se tornou o apóstolo Paulo.", "Atos 9:1-31", "Entender que Jesus transforma vidas radicalmente", "O maior perseguidor da igreja se tornou o maior missioneiro da história. Ninguém está longe da graça de Deus."),
    ("Atos: A Igreja em Expansao", 6, "Atos 10 - Cornélio e Pedro", "Deus mandou um anjo a Cornélio, romano piedoso. Em sonho, Pedro viu um pano com animais e Deus disse: \"O que Deus purificou, não chames de impuro.\" Pedro entendeu que o evangelho é para todos.", "Atos 10:1-48", "Compreender que o evangelho é para todas as nações", "A visão do pano ensinou a Pedro que a graça de Deus não faz diferença entre judeus e gentios."),
    ("Atos: A Igreja em Expansao", 7, "Atos 16 - A Conversão em Filipos", "Paulo e Silas foram presos em Filipos, mas cantavam hinos na prisão. Um terremoto abriu as portas. O carcereiro perguntou: \"Que devo fazer para ser salvo?\" Resposta: \"Crê no Senhor Jesus.\"", "Atos 16:16-34", "Experimentar a liberdade que vem da fé em Jesus", "Mesmo na prisão, Paulo e Silas louvavam. Deus abriu as portas e salvou o carcereiro e toda a sua família."),
    ("Atos: A Igreja em Expansao", 8, "Atos 17 - O Areópago", "Paulo pregou em Atenas, no Areópago, citando poetas gregos. Falou do \"Deus desconhecido\" que deu vida a todos. Alguns zombaram, outros creram.", "Atos 17:16-34", "Usar a cultura para comunicar o evangelho", "Paulo usou a cultura local para apresentar o Deus verdadeiro, adaptando sua mensagem sem comprometer a verdade."),
    ("Atos: A Igreja em Expansao", 9, "Atos 21 - A Prisão em Jerusalém", "Paulo voltou a Jerusalém sabendo que seria preso. Multidões o atacaram, romanos o prenderam para protegê-lo. Paulo usou cada oportunidade para pregar.", "Atos 21:1-40", "Perseguir o chamado mesmo com custos", "Paulo sabia do perigo, mas cumpriu o chamado. Na prisão, sempre encontrava forma de testemunhar."),
    ("Atos: A Igreja em Expansao", 10, "Atos 28 - O Evangelho em Roma", "Paulo chegou a Roma como prisioneiro, mas alugou uma casa e recebeu os líderes judeus. Pregou o Reino de Deus com franqueza. O livro termina com Paulo livre.", "Atos 28:16-31", "Reconhecer que o evangelho não pode ser detido", "Mesmo preso em Roma, Paulo continuou pregando. O livro de Atos termina aberto: o evangelho continua se espalhando."),
    ("Romanos: O Evangelho da Graça", 1, "Romanos 1-2: O Pecado Geral", "Paulo argumenta que tanto os gentios quanto os judeus estão sob o julgamento de Deus. Todos pecaram e faltam da glória de Deus. Nenhum sistema religioso ou moral pode livrar o ser humano da culpa.", "Romanos 1:18-3:20", "Compreender que todos os seres humanos são pecadores diante de Deus", "Toda humanidade, sem exceção, é culpada diante de Deus. Nem conhecimento da Lei nem a criação deixam desculpa."),
    ("Romanos: O Evangelho da Graça", 2, "Romanos 3: Justificação pela Fé", "A justificação é pela graça, mediante a redenção que há em Cristo Jesus. Deus propôs o propiciatório pelo sangue de fé, para demonstrar a Sua justiça. A justificação é um dom, não por obras.", "Romanos 3:21-31", "Entender o que significa ser justificado pela fé em Jesus", "A justificação é um ato gratuito de Deus que nos declara justos com base na obra de Cristo, não nas nossas obras."),
    ("Romanos: O Evangelho da Graça", 3, "Romanos 4: Abraão Pela Fé", "Abraão acreditou em Deus e lhe foi imputada justiça. Ele recebeu a promessa não pelas obras, mas pela imputação da fé. A justificação pela fé é o modelo de Abraão para todos os crentes.", "Romanos 4:1-25", "Reconhecer que Abraão é o exemplo máximo da justificação pela fé", "Assim como Abraão creu em Deus e lhe foi contado como justiça, nós também somos justificados pela fé, não pelas obras."),
    ("Romanos: O Evangelho da Graça", 4, "Romanos 5: Paz com Deus", "Sendo justificados pela fé, temos paz com Deus através de nosso Senhor Jesus Cristo. A graça de Deus abunda onde o pecado aumentou. O amor de Deus foi derramado em nossos corações.", "Romanos 5:1-11", "Experimentar a paz que vem da justificação pela fé", "A justificação traz paz com Deus, acesso à graça e esperança da glória de Deus. O amor de Cristo nos salva."),
    ("Romanos: O Evangelho da Graça", 5, "Romanos 6: Libertação do Pecado", "Devemos viver como mortos para o pecado e vivos para Deus. Fomos batizados com Cristo na morte e ressurreição. O pecado não terá domínio sobre nós, pois estamos debaixo da graça.", "Romanos 6:1-23", "Entender que a graça não é licença para pecar", "A graça liberta do pecado, não autoriza a viver nele. Somos novas criaturas em Cristo."),
    ("Romanos: O Evangelho da Graça", 6, "Romanos 7: A Luta Interior", "Paulo descreve a luta entre a carne e o espírito. \"O bem que quero não faço, e o mal que não quero, isso pratico.\" A lei é santa, mas a carne é fraca.", "Romanos 7:15-25", "Reconhecer a luta interior de todo cristão maduro", "A luta contra o pecado é real, mas Cristo é a vitória. A lei mostra o pecado, mas não liberta dele."),
    ("Romanos: O Evangelho da Graça", 7, "Romanos 8: Sem Condenação", "Não há condenação para os que estão em Cristo Jesus. O Espírito Santo liberta da lei do pecado e da morte. Nada pode nos separar do amor de Deus em Cristo.", "Romanos 8:1-39", "Viver na certeza de não haver condenação para quem está em Cristo", "A vida no Espírito traz liberdade, adoção como filhos e segurança eterna no amor de Deus."),
    ("Romanos: O Evangelho da Graça", 8, "Romanos 9: A Eleição Divina", "Paulo discute a soberania de Deus na escolha de Israel e na eleição dos crentes. Deus tem misericórdia de quem quer e endurece quem quer. O barro não pode questionar o oleiro.", "Romanos 9:1-24", "Entender a soberania de Deus na eleição", "Deus é soberano na Sua escolha, mas isso não anula a responsabilidade humana de crer."),
    ("Romanos: O Evangelho da Graça", 9, "Romanos 12: Viva em Sacrifício", "Paulo pede que ofereçamos nossos corpos como sacrifício vivo e santo a Deus. Não nos conformemos com este mundo, mas transformemo-nos pela renovação do entendimento.", "Romanos 12:1-21", "Renovar a vida como sacrifício vivo a Deus", "A vida cristã prática envolve consagração, serviço, amor genuíno e não retaliação."),
    ("Romanos: O Evangelho da Graça", 10, "Romanos 13: Submissão às Autoridades", "Todo poder vem de Deus. Devemos estar sujeitos às autoridades, pagar impostos, honrar todos e amar ao próximo como a nós mesmos. O amor cumpre a Lei.", "Romanos 13:1-14", "Entender a relação entre fé cristã e autoridade civil", "Deus estabeleceu autoridades para ordem. O crente deve submeter-se, mas o amor é a Lei suprema."),
    ("Corintios e Galatas", 1, "1 Coríntios 1: Sabedoria da Cruz", "Paulo repreende as divisões na igreja de Corinto. A sabedoria de Deus é loucura para o mundo. Cristo crucificado é o poder e sabedoria de Deus, não a retórica humana.", "1 Corintios 1:18-31", "Reconhecer que a sabedoria de Deus está na cruz", "O mundo busca sabedoria eloquente, mas Deus usa o que é fraco e louco aos olhos do mundo para confundir os sábios."),
    ("Corintios e Galatas", 2, "1 Coríntios 6: O Corpo é Templo", "Paulo condena a imoralidade sexual e lembra que o corpo do crente é templo do Espírito Santo. Fomos comprados por preço: glorifiquemos a Deus no corpo.", "1 Corintios 6:12-20", "Cuidar do corpo como templo do Espírito Santo", "O corpo não é para a imoralidade, mas para glorificar a Deus. Somos templos do Espírito."),
    ("Corintios e Galatas", 3, "1 Coríntios 13: O Capítulo do Amor", "Sem amor, nada temos. O amor é paciente, bondoso, não se irrita, não busca seus interesses. A fé, a esperança e o amor permanecem, mas o maior é o amor.", "1 Corintios 13:1-13", "Entender a centralidade do amor na vida cristã", "O amor é o mais excelente caminho. Sem ele, todos os dons e sacrifícios são vãos."),
    ("Corintios e Galatas", 4, "1 Coríntios 15: A Ressurreição", "Paulo recorda que Cristo ressuscitou e apareceu a mais de 500 irmãos. Se Cristo não ressuscitou, a fé é vã. Mas Cristo é a primícia dos que dormem.", "1 Corintios 15:1-58", "Firmar a fé na ressurreição de Cristo e na nossa", "A ressurreição de Cristo é o fundamento da fé cristã. Sem ela, não há esperança."),
    ("Corintios e Galatas", 5, "2 Coríntios 4: Tesouros de Barro", "Paulo compara o ministério a tesouros em vasos de barro. Sofremos, mas não desanimamos. O poder é de Deus, não de nós. O homem exterior perece, mas o interior se renova.", "2 Corintios 4:7-18", "Valorizar o tesouro do evangelho em vasos frágeis", "Nossa fragilidade mostra o poder de Deus. As aflições são leves comparadas à glória eterna."),
    ("Corintios e Galatas", 6, "2 Coríntios 12: Graça Suficiente", "Paulo pede que o espinho na carne seja removido, mas Deus responde: \"Minha graça te basta, porque o meu poder se aperfeiçoa na fraqueza.\" Paulo se gloria nas fraquezas.", "2 Corintios 12:1-10", "Confiar na graça suficiente de Deus nas fraquezas", "Deus permite fraquezas para que Seu poder se manifeste. A graça de Deus é sempre suficiente."),
    ("Corintios e Galatas", 7, "Gálatas 2: Justificação pela Fé", "Paulo confrontou Pedro por se separar dos gentios por medo. A justificação não vem pelas obras da Lei, mas pela fé em Cristo. Cristo morreu pelo pecado dos injustos.", "Galatas 2:15-21", "Firmar a justificação pela fé, não pelas obras da Lei", "A obra da Lei não justifica. Somente a fé em Cristo nos declara justos diante de Deus."),
    ("Corintios e Galatas", 8, "Gálatas 3: Filhos de Deus pela Fé", "Todos que são de Cristo foram batizados nele e são descendência de Abraão. Não há nem grego nem judeu. A promessa veio pela fé, não pela Lei.", "Galatas 3:23-29", "Entender que somos filhos de Deus pela fé em Cristo", "Em Cristo, todos são um. A distinção entre judeu e gentio, escravo e livre, homem e mulher, é superada pela fé."),
    ("Corintios e Galatas", 9, "Gálatas 4: Libertados", "Enquanto éramos meninos, estávamos sob servidão, mas Deus enviou o Seu Filho para resgatar os que estavam sob a Lei, para que recebêssemos a adoção.", "Galatas 4:1-7", "Compreender a liberdade que temos em Cristo", "Deus nos libertou da escravidão da Lei para vivermos como filhos amados, guiados pelo Espírito."),
    ("Corintios e Galatas", 10, "Gálatas 5: O Fruto do Espírito", "Cristo nos libertou para a liberdade. Andai no Espírito, e não satisfareis os desejos da carne. O fruto do Espírito é amor, gozo, paz, mansidão, bondade, fé, temperança.", "Galatas 5:16-26", "Cultivar o fruto do Espírito na vida diária", "A vida no Espírito se manifesta em fruto, não em obras da carne. A liberdade é para servir pelo amor."),
    ("Efesios, Filipenses, Colossenses", 1, "Efésios 1: Abençoados com Toda Bênção", "Deus nos abençoou com todas as bênçãos espirituais nos lugares celestiais em Cristo. Ele nos escolheu antes da fundação do mundo, predestinando‑nos para filhos adotivos.", "Efesios 1:3-14", "Reconhecer as bênçãos espirituais que temos em Cristo", "Deus nos abençoou abundantemente e espiritualmente em Cristo, com escolha, adoção, redenção e selamento."),
    ("Efesios, Filipenses, Colossenses", 2, "Efésios 2: Salvos pela Graça", "Éramos mortos em pecados, mas Deus nos vivificou com Cristo. Somos salvos pela graça, mediante a fé, não por obras. Somos feitura de Deus, criados para boas obras.", "Efesios 2:1-10", "Entender que somos vivificados e salvos pela graça de Deus", "Deus nos tirou da morte espiritual, nos sentou com Cristo, e nos criou para boas obras."),
    ("Efesios, Filipenses, Colossenses", 3, "Efésios 3: O Amor Infinito de Cristo", "Paulo ora para que os efésios compreendam o amor de Cristo, que excede todo conhecimento. Para aquele que pode fazer infinitamente mais, glória na igreja.", "Efesios 3:14-21", "Experimentar o amor de Cristo que excede todo conhecimento", "O amor de Cristo é imensurável, e Deus pode fazer muito mais do que pedimos ou pensamos."),
    ("Efesios, Filipenses, Colossenses", 4, "Efésios 4: A Unidade do Espírito", "Paulo exorta à unidade da fé e do conhecimento do Filho de Deus. Cada membro do corpo de Cristo tem uma função. A verdade em amor faz crescer em Cristo.", "Efesios 4:1-16", "Buscar a unidade na diversidade de dons", "A igreja é um corpo com muitos membros. A verdade em amor promove o crescimento."),
    ("Efesios, Filipenses, Colossenses", 5, "Efésios 6: A Armadura de Deus", "Veste a armadura de Deus para resistir às ciladas do diabo. Cinto da verdade, couraça da justiça, escudo da fé, capacete da salvação, espada do Espírito e oração.", "Efesios 6:10-20", "Vestir‑se diariamente com a armadura de Deus", "A guerra espiritual é real. Deus fornece toda a armadura necessária para resistir ao inimigo."),
    ("Efesios, Filipenses, Colossenses", 6, "Filipenses 1: Alegria na Prisão", "Preso em Roma, Paulo escreve com alegria. O que importa é que Cristo seja anunciado. Para mim viver em Cristo, e morrer é ganho. Ele está confiante que será liberto.", "Filipenses 1:12-26", "Cultivar alegria independentemente das circunstâncias", "Mesmo na prisão, Paulo tinha alegria porque Cristo era anunciado. A sua prioridade era Cristo."),
    ("Efesios, Filipenses, Colossenses", 7, "Filipenses 2: A Humildade de Cristo", "Cristo, sendo em forma de Deus, não teve por usurpação ser igual a Deus, mas esvaziou-se, tomando a forma de servo. Deus o exaltou e lhe deu o nome acima de todo nome.", "Filipenses 2:5-11", "Imitar a humildade de Cristo em nossa vida", "A humildade de Cristo é o exemplo supremo. Ele se humilhou até a morte na cruz, e Deus o exaltou."),
    ("Efesios, Filipenses, Colossenses", 8, "Filipenses 4: Posso Todas as Coisas", "Paulo aprendeu a contentar-se em toda situação. O segredo é a força de Cristo. E o Deus da paz estará convosco. Fixai o pensamento no que é verdadeiro, justo e louvável.", "Filipenses 4:4-13", "Aprender o segredo do contentamento em Cristo", "O contentamento não depende das circunstâncias, mas da força que Cristo dá."),
    ("Efesios, Filipenses, Colossenses", 9, "Colossenses 1: A Supremacia de Cristo", "Cristo é a imagem do Deus invisível, o primogênito de toda criação. Por Ele foram criadas todas as coisas. Ele é a cabeça da igreja e o primeiro dos que ressuscitaram dos mortos.", "Colossenses 1:15-20", "Reconhecer a supremacia absoluta de Cristo sobre toda a criação", "Cristo é soberano sobre toda a criação, a igreja, e todas as coisas são sustentadas por Ele."),
    ("Efesios, Filipenses, Colossenses", 10, "Colossenses 3: Vida Nova", "Busquei as coisas lá de cima. Revesti-vos do homem novo, renovado para o conhecimento, segundo a imagem do Criador. Deixai de lado a velha vida e vivei em Cristo.", "Colossenses 3:1-17", "Viver a vida nova em Cristo, mortos para o pecado", "A vida cristã prática envolve deixar o velho homem, vestir o novo e viver em amor e sabedoria."),
    ("Tessalonicenses e Pastorais", 1, "1 Tessalonicenses 4: O Arrebatamento", "Paulo instrui sobre a santidade e a vinda do Senhor. Os mortos em Cristo ressuscitarão primeiro, e depois nós, que ficarmos, seremos arrebatados juntamente com eles.", "1 Tessalonicenses 4:13-18", "Entender a esperança do arrebatamento da igreja", "Deus não quis que ficasseis ignorantes sobre os que dormem. Seremos arrebatados para estar com o Senhor."),
    ("Tessalonicenses e Pastorais", 2, "1 Tessalonicenses 5: O Dia do Senhor", "O dia do Senhor vem como um ladrão na noite. Somos filhos da luz, não da escuridão. Examinai tudo e guarda o que é bom. Orai sem cessar.", "1 Tessalonicenses 5:1-28", "Viver preparados para a vinda do Senhor", "O crente deve viver como filho da luz, vigilante, orando e rejubilando sempre."),
    ("Tessalonicenses e Pastorais", 3, "2 Tessalonicenses 3: A Preguiça", "Paulo ordena que os preguiçosos não comam. Aquele que não quer trabalhar, não coma. Não desanimem no bem. Não andem como inquietos.", "2 Tessalonicenses 3:6-15", "Cultivar disciplina e trabalho na vida cristã", "A fé produtiva e o trabalho honesto são parte da vida cristã. A preguiça desonra o evangelho."),
    ("Tessalonicenses e Pastorais", 4, "1 Timóteo 2: Oração por Todos", "Paulo pede que se façam intercessões, orações, ações de graça por todos os homens. Quer que se reze por reis e por todos os que estão em autoridade.", "1 Timoteo 2:1-8", "Entender a importância da oração pela sociedade", "A oração deve ser feita por todos os homens, sem ira nem disputas. Deus quer que todos sejam salvos."),
    ("Tessalonicenses e Pastorais", 5, "1 Timóteo 3: Qualificações dos Líderes", "Paulo lista qualificações para bispos e diáconos: irrepreensível, marido de uma só mulher, cheio do Espírito, apto a ensinar, não dado ao vinho.", "1 Timoteo 3:1-13", "Reconhecer as qualificações bíblicas para líderes da igreja", "A liderança na igreja exige integridade, sabedoria e santidade de vida."),
    ("Tessalonicenses e Pastorais", 6, "1 Timóteo 4: Timóteo, Exemplo dos Fiéis", "Paulo encoraja Timóteo a usar bem o seu dom, a se exercitar na piedade e a persistir no ensino. Deve ser modelo em palavra, conduta, amor, fé e castidade.", "1 Timoteo 4:6-16", "Ser modelo de fé e conduta para os outros", "O servo de Deus deve se exercitar na piedade, ser diligente no ensino e viver o que ensina."),
    ("Tessalonicenses e Pastorais", 7, "2 Timóteo 4: Combate o Bom Combate", "Paulo, prestes a ser martirizado, encoraja Timóteo: prega a palavra, insta a tempo e fora de tempo, repreende, suplica. Combate o bom combate da fé.", "2 Timoteo 4:1-8", "Ser corajoso e fiel no ministério até o fim", "O crente deve persistir na verdade, mesmo quando muitos não suportarão a sã doutrina."),
    ("Tessalonicenses e Pastorais", 8, "Tito 2: A Graça que Salva", "A graça de Deus apareceu, trazendo salvação a todos os homens. Ela nos ensina a negar a impiedade e viver de forma justa e sensata neste mundo.", "Tito 2:11-14", "Entender que a graça traz disciplina e salvação", "A graça não é licença para pecar, mas a força para viver santo, aguardando a vinda de Cristo."),
    ("Tessalonicenses e Pastorais", 9, "Tito 3: Obras Boas", "Salvos não por obras de justiça que nós mesmos praticamos, mas pela Sua misericórdia. Entretanto, somos criados em Cristo para boas obras.", "Tito 3:3-8", "Viver em boas obras como fruto da salvação", "A salvação é pela graça, mas o crente é chamado a praticar boas obras e ser produtivo."),
    ("Tessalonicenses e Pastorais", 10, "Filemom: Perdão", "Onésimo, escravo de Filemom, fugiu e converteu‑se pelo ministério de Paulo. Paulo pede a Filemom que receba de volta Onésimo não como escravo, mas como irmão amado.", "Filemon 1:1-25", "Praticar o perdão e a reconciliação entre irmãos na fé", "O evangelho transforma relações humanas. Em Cristo, não há escravo nem livre."),
    ("Hebreus: Cristo Superior", 1, "Hebreus 1: O Filho Revelado", "Deus falou por muitos modos, mas agora nos falou pelo Seu Filho. Cristo é a imagem exata do Deus invisível, sustentando todas as coisas pela palavra do Seu poder.", "Hebreus 1:1-4", "Reconhecer que Cristo é a revelação suprema de Deus", "Cristo supera todos os profetas e anjos. Ele é o Filho, herdador de todas as coisas."),
    ("Hebreus: Cristo Superior", 2, "Hebreus 2: Um Pouco Menor", "Por um tempo, Cristo ficou um pouco menor que os anjos para sofrer a morte e coroar‑nos de graça e honra. Assim tornou‑se autor da salvação eterna.", "Hebreus 2:5-18", "Entender o sofrimento voluntário de Cristo por nós", "Cristo se humilhou temporariamente para nos trazer a salvação e ser nosso sumo sacerdote misericordioso."),
    ("Hebreus: Cristo Superior", 3, "Hebreus 3: Jesus Superior a Moisés", "Jesus é digno de maior glória que Moisés, assim como o construtor é maior que a casa. Moisés servo, mas Cristo Filho sobre a casa.", "Hebreus 3:1-6", "Reconhecer que Cristo é superior até mesmo a Moisés", "Moisés foi fiel como servo, mas Cristo é fiel como Filho sobre toda a casa de Deus."),
    ("Hebreus: Cristo Superior", 4, "Hebreus 4: Entrando no Descanso", "Deus preparou um descanso para o Seu povo. Não endureçais os vossos corações. A Palavra de Deus é viva e eficaz, penetrante até dividir espírito e alma.", "Hebreus 4:1-16", "Buscar o descanso que Deus oferece pela fé", "Há um descanso espiritual para os que creem. A Palavra de Deus é cortante e penetrante."),
    ("Hebreus: Cristo Superior", 5, "Hebreus 5‑6: O Sumo Sacerdote", "Cristo se tornou sumo sacerdote para sempre, segundo a ordem de Melquisedeque. Perseverarei na fé e no ensino, não caindo de novo no arrependimento.", "Hebreus 5:10-6:12", "Firmar a fé e não cair para trás", "A perseverança é fundamental. Cristo é nosso sumo sacerdote eterno, capaz de compadecer‑se."),
    ("Hebreus: Cristo Superior", 6, "Hebreus 7: A Melhor Aliança", "Melquisedeque, rei de Salém, sacerdote do Deus Altíssimo, abençoou Abraão. Cristo é sumo sacerdote eterno segundo essa ordem, estabelecendo melhor aliança.", "Hebreus 7:1-28", "Entender por que a aliança de Cristo é melhor", "O sacerdócio de Melquisedeque é eterno e superior ao de Arão. A aliança de Cristo é melhor e irrevogável."),
    ("Hebreus: Cristo Superior", 7, "Hebreus 9: O Sangue Definitivo", "O sangue de bodes e bezerros não pode remover pecados. Cristo entrou no santo dos santos com o seu próprio sangue, oferecendo-se uma vez por todas.", "Hebreus 9:11-28", "Reconhecer que o sangue de Cristo é definitivo e suficiente", "O sangue de Cristo é mais precioso e eficaz que qualquer sacrifício antigo. Uma vez, bastou."),
    ("Hebreus: Cristo Superior", 8, "Hebreus 10: O Sacrifício Único", "É impossível que sangue de touros e bodes tire pecados. Quando Cristo se ofereceu, acabou o pecado para sempre. Entremos com confiança ao trono da graça.", "Hebreus 10:1-23", "Ter confiança no sacrifício único e perfeito de Cristo", "O sacrifício de Cristo é único e perfeito. Podemos ter certeza da nossa salvação nele."),
    ("Hebreus: Cristo Superior", 9, "Hebreus 11: A Fé", "A fé é a certeza daquilo que esperamos e a prova das coisas que não vemos. Abraão, Moisés, Raabe e muitos outros viveram pela fé e não receberam a promessa completa.", "Hebreus 11:1-40", "Cultivar uma fé firme e inabalável", "Fé é agir com base na palavra de Deus, mesmo não vendo. O exemplo dos antigos nos encoraja."),
    ("Hebreus: Cristo Superior", 10, "Hebreus 12: A Corrida da Fé", "Nossa fé é cercada por tão grande nuvem de testemunhas. Corramos com perseverança a carreira que temos diante de nós, olhando para Jesus, autor e consumador da fé.", "Hebreus 12:1-29", "Correr com perseverança a carreira da fé", "Os antigos nos cercam. Cristo é nosso exemplo e objetivo. Não nos cansemos de seguir o caminho."),
    ("Tiago e Pedro: Fe em Acao", 1, "Tiago 1: Provações", "Considerai pura a alegria quando entrais em provações de muitas sortes, porque a fé, provada, produz perseverança. Se falta sabedoria, peça a Deus.", "Tiago 1:2-12", "Encontrar propósito nas provações da vida", "As provações produzem perseverança, que produz maturidade. Deus dá sabedoria liberalmente a quem pede."),
    ("Tiago e Pedro: Fe em Acao", 2, "Tiago 2: Fé sem Obras", "Se alguém diz que tem fé e não tem obras, que lhe aproveita? A fé sem obras é morta. Abraão foi justificado pelas obras quando ofereceu Isaque.", "Tiago 2:14-26", "Entender que a fé genuína produz obras", "A fé verdadeira se demonstra por ações. Fé e obras caminham juntas na vida do crente."),
    ("Tiago e Pedro: Fe em Acao", 3, "Tiago 3: A Língua", "A língua é um pequeno membro, mas faz grandes estragos. Ninguém pode domar a língua. Ela é um mundo de maldade, cheia de veneno mortal.", "Tiago 3:1-12", "Aprender a controlar a própria língua", "A língua pode destruir ou construir. O crente deve ser cuidadoso com suas palavras."),
    ("Tiago e Pedro: Fe em Acao", 4, "Tiago 4: Humildade", "Resisti ao diabo, e fugirá de vós. Aproximai-vos de Deus, e Ele se aproximará de vós. Não vanglorieis de amanhã. Humilhai-vos diante do Senhor, e vos exaltará.", "Tiago 4:1-10", "Viver em humildade diante de Deus e dos outros", "A soberba leva à queda. A humildade atrai a exaltação divina. Proximidade com Deus e consequência de humildade."),
    ("Tiago e Pedro: Fe em Acao", 5, "Tiago 5: A Oração dos Justos", "A oração é muito eficaz. Elias era homem sujeito às mesmas paixões que nós, mas orou e não choveu por três anos. Confessai as vossas culpas uns aos outros e orai.", "Tiago 5:13-18", "Valorizar o poder da oração no ministério", "A oração é poderosa e eficaz. Os justos devem orar uns pelos outros."),
    ("Tiago e Pedro: Fe em Acao", 6, "1 Pedro 1: Viva Esperança", "Nascemos de novo pela palavra viva e eterna de Deus. Nossa fé, mais preciosa que o ouro provado pelo fogo, resulta em louvor, glória e honra.", "1 Pedro 1:3-9", "Cultivar uma viva esperança na redenção", "A herança é incorruptível. Nossa fé, provada pelo fogo, é mais preciosa que o ouro."),
    ("Tiago e Pedro: Fe em Acao", 7, "1 Pedro 2: Pedras Vivas", "Vos mesmos, como pedras vivas, sede edificados espiritualmente em casa sacerdotal. Cristo é a pedra angular, a pedra de esquina, a pedra do tropeço.", "1 Pedro 2:1-10", "Ser parte viva da casa espiritual de Deus", "Somos pedras vivas no templo espiritual. Cristo é a pedra angular que sustenta tudo."),
    ("Tiago e Pedro: Fe em Acao", 8, "1 Pedro 3: Casamento", "Vós, mulheres, sujeitai-vos ao vosso marido. Vós, maridos, vivei com elas com entendimento, honrando-as como vasos mais fracos. A graça é a herança da vida.", "1 Pedro 3:1-7", "Viver em harmonia no casamento segundo Deus", "O amor mútuo, o respeito e a oração fortalecem o casamento cristão."),
    ("Tiago e Pedro: Fe em Acao", 9, "2 Pedro 1: Crescimento Espiritual", "Procurai tornar ainda mais firmes a vocação e a eleição. Acrescentai a vossa fé à virtude, a virtude ao conhecimento, o conhecimento à temperança.", "2 Pedro 1:3-11", "Crescer ativamente na fé e nas virtudes", "O crescimento espiritual e intencional. Cada virtude leva a outra, produzindo frutos."),
    ("Tiago e Pedro: Fe em Acao", 10, "2 Pedro 3: O Dia do Senhor", "O dia do Senhor virá como ladrão. Nos novos céus e nova terra, habita justiça. Aguardai e apressai-vos pela vinda do Senhor.", "2 Pedro 3:8-13", "Viver na expectativa do dia do Senhor", "Deus não tarda a sua promessa. Devemos viver santamente esperando os novos céus e terra."),
    ("Joao e Cartas Breves", 1, "1 João 1: Luz e Comunhão", "A vida eterna era com o Pai e foi revelada aos apóstolos. Anunciamos a vós o que vimos e ouvimos, para que também tenhais comunhão conosco e com o Pai.", "1 Joao 1:1-4", "Cultivar comunhão genuína com Deus e com os irmãos", "A comunhão com Deus se dá pela luz e pela confissão do pecado. Jesus é a luz que purifica."),
    ("Joao e Cartas Breves", 2, "1 João 2: O Advogado", "Se alguém pecar, temos um advogado junto ao Pai, Jesus Cristo, o justo. Ele é a propiciação pelos nossos pecados. Guardai os Seus mandamentos.", "1 Joao 2:1-6", "Ter confiança no advogado Jesus Cristo", "Jesus intercede por nós. Quem conhece a Deus guarda os Seus mandamentos."),
    ("Joao e Cartas Breves", 3, "1 João 3: Filhos de Deus", "Vede que amor nos deu o Pai, para que fôssemos chamados filhos de Deus. Ninguém o viu, mas se amamos uns aos outros, Deus permanece em nós.", "1 Joao 3:1-24", "Viver como filhos amados de Deus", "Somos filhos de Deus e seremos como Ele. O amor fraternal prova que estamos nele."),
    ("Joao e Cartas Breves", 4, "1 João 4: Deus e Amor", "Deus é amor. Quem ama a Deus ama também ao seu irmão. Neles se revelou o amor de Deus: em nos ter mandado o Seu Filho unigênito como propiciação.", "1 Joao 4:7-21", "Amar porque Deus amou primeiro", "O amor é a essência de Deus. Quem O ama, ama a seus irmãos. O amor perfeito expulsa o medo."),
    ("Joao e Cartas Breves", 5, "1 João 5: A Vitória", "Toda a fé no nome do Filho de Deus nos vence o mundo. A vitória que vence o mundo é a nossa fé. Sabemos que o Filho de Deus veio e nos deu entendimento.", "1 Joao 5:1-12", "Viver na certeza da vitória pela fé", "A fé em Cristo nos dá vitória sobre o mundo. Temos a certeza da vida eterna."),
    ("Joao e Cartas Breves", 6, "2 João: A Verdade", "A verdade permanece em nós e estará conosco para sempre. Guardai-vos dos enganadores que não trazem a doutrina de Cristo. A graça, a misericórdia e a paz estejam conosco.", "2 Joao 1:1-13", "Guarda a verdade e não se desvie do evangelho", "A verdade em Cristo é eterna. Devemos rejeitar falsos ensinos e andar na verdade."),
    ("Joao e Cartas Breves", 7, "3 João: Gaio", "Gaio é elogiado por sua hospitalidade e fidelidade à verdade. Diotrefes, ao contrário, recusa receber os irmãos e fala maldade. Demétrio é testemunhado por todos.", "3 Joao 1:1-15", "Praticar hospitalidade e fidelidade à verdade", "A hospitalidade genuína é fruto da fé. Gaio é exemplo de amor e serviço aos irmãos."),
    ("Joao e Cartas Breves", 8, "Judas: Defenda a Fé", "Lutai pela fé que uma vez foi entregue aos santos. Há homens perversos que transformam a graça de Deus em licença para pecar. Mas Aquele que pode guardar-vos sem tropeço.", "Jude 1:3-25", "Defender a fé ortodoxa contra falsos ensinadores", "A fé precisa ser defendida. Falsos mestres entram na igreja para destruir."),
    ("Joao e Cartas Breves", 9, "Lamentações 3: Misericórdias de Deus", "As misericórdias de Deus não se esgotam. São novas a cada manhã. Grande é a fidelidade do Senhor. O Senhor não rejeita para sempre.", "Lamentacoes 3:22-33", "Renovar a esperança nas misericórdias de Deus", "Mesmo na maior tribulação, as misericórdias de Deus se renovam. Sua fidelidade é grande."),
    ("Joao e Cartas Breves", 10, "Apocalipse 1: Jesus Glorificado", "João viu uma visão do Filho do homem, vestido com uma faixa dourada, com cabelos brancos como lã, olhos como chamas de fogo. \"Eu sou o Alfa e o Ômega.\"", "Apocalipse 1:9-20", "Rever a glória e o poder de Jesus Cristo", "Jesus é glorificado e poderoso. Ele morreu e vive para sempre. Ele tem as chaves da morte e do Hades."),
    ("Apocalipse: A Consumacao", 1, "Apocalipse 1: A Revelação", "João recebeu a revelação de Jesus Cristo. Ele a viu em visão na ilha de Patmos. O Alfa e o Ômega, que era, que é e que há de vir, enviou seu anjo para mostrar as coisas que devem brevemente acontecer.", "Apocalipse 1:1-8", "Entender a natureza e o propósito do Apocalipse", "O Apocalipse é a revelação de Jesus Cristo, dada para mostrar aos servos o que deve acontecer."),
    ("Apocalipse: A Consumacao", 2, "Apocalipse 4-5: O Trono e o Cordeiro", "João viu o trono no céu e 24 anciãos em volta. No meio do trono estava o Cordeiro como tendo sido morto, digno de receber poder, riquezas, sabedoria, honra e glória.", "Apocalipse 4:1-5:14", "Adorar a Deus no trono e ao Cordeiro digno", "O Cordeiro que foi morto e digno de abrir o livro dos selos. Toda a criação o adora."),
    ("Apocalipse: A Consumacao", 3, "Apocalipse 6: Os Selos", "O Cordeiro abriu os selos um por um. O primeiro selo: cavaleiro branco (conquista). O segundo: vermelho (guerra). O terceiro: preto (fome). O quarto: verde (morte).", "Apocalipse 6:1-17", "Reconhecer os juízos que precedem a consumação", "Os selos representam juízos progressivos sobre a terra. O sétimo selo traz silêncio no céu."),
    ("Apocalipse: A Consumacao", 4, "Apocalipse 7: A Multidão", "Uma multidão enorme, que ninguém podia contar, de todas as nações, tribos, povos e língua, estava de pé diante do trono e do Cordeiro, com palmas nas mãos.", "Apocalipse 7:9-17", "Ter visão da multidão dos resgatados", "De todos os povos e nações, a multidão dos redimidos adora a Deus e ao Cordeiro."),
    ("Apocalipse: A Consumacao", 5, "Apocalipse 8-9: As Trombetas", "Sete anjos tocam trombetas. Grandes destruições caem sobre a terra: metade das árvores queimadas, os mares transformados em sangue, trevas sobre a terra.", "Apocalipse 8:1-9:21", "Entender a gravidade dos juízos das trombetas", "Os juízos se intensificam. Mesmo assim, os homens não se arrependem de suas obras."),
    ("Apocalipse: A Consumacao", 6, "Apocalipse 12: A Mulher e o Dragão", "Uma mulher revestida de sol, com a lua sob seus pés, deu à luz um varão que governaria as nações. O grande dragão, a serpente antiga, perseguiu a mulher e o seu descendente.", "Apocalipse 12:1-17", "Reconhecer a guerra espiritual entre o bem e o mal", "A mulher representa Israel/Igreja. O dragão é Satanás. O descendente é Cristo. A guerra espiritual e real."),
    ("Apocalipse: A Consumacao", 7, "Apocalipse 13: A Besta", "Uma besta subiu do mar, com dez chifres e sete cabeças, blasfemando contra Deus. O mundo inteiro adorou a besta. Outra besta fez um nome para a primeira.", "Apocalipse 13:1-18", "Reconhecer os sistemas malignos contra o povo de Deus", "A besta representa poderes políticos anticristos. A marca da besta controla o comércio e a vida."),
    ("Apocalipse: A Consumacao", 8, "Apocalipse 14: O Ceifão", "Anjos ceifam a terra. O ceifador é mandado porque a terra já está madura para o juízo. Outro anjo ceifou os cachos da terra, atirando-os no grande lagar da ira de Deus.", "Apocalipse 14:14-20", "Entender a vindima final e o juízo de Deus", "A terra está madura para o juízo. Deus separa os justos e os injustos."),
    ("Apocalipse: A Consumacao", 9, "Apocalipse 19: O Cavaleiro Fiel", "O cavaleiro (Jesus) aparece montado em um cavalo branco. Seus olhos são como chamas de fogo. Na sua boca uma espada afiada. É rei dos reis e senhor dos senhores.", "Apocalipse 19:11-21", "Vitória final de Cristo sobre todos os inimigos", "Jesus retorna como juiz e rei. É justo e fiel. As nações são pastoreadas com vara de ferro."),
    ("Apocalipse: A Consumacao", 10, "Apocalipse 21-22: A Nova Jerusalém", "Vi os novos céus e a nova terra. A Nova Jerusalém desce do céu, preparada como uma noiva adornada. Não haverá mais lágrimas, nem morte, nem dor. O Alfa e o Ômega está ali.", "Apocalipse 21:1-22:21", "Esperar a Nova Jerusalém e a consumação de todas as coisas", "A promessa final é a restauração completa. Sem lágrimas, sem morte, sem dor. A presença de Deus é eterna."),
    ("Sabedoria e Poesia", 1, "Provérbios 1: O Princípio da Sabedoria", "O temor do Senhor é o princípio da sabedoria. Os provérbios ensinam sabedoria, disciplina e entendimento. O filho prudente escuta o pai e a mãe.", "Proverbios 1:1-33", "Entender que o temor do Senhor é a base de toda sabedoria", "A sabedoria bíblica começa com reverência a Deus. Sem isso, todo conhecimento é vazio."),
    ("Sabedoria e Poesia", 2, "Provérbios 3: Confie no Senhor", "Confia no Senhor de todo o teu coração e não te estribes no teu próprio entendimento. Reconhece‑O em todos os teus caminhos, e Ele endireitará as tuas veredas.", "Proverbios 3:1-26", "Aprender a confiar plenamente em Deus em todas as situações", "A confiança em Deus substitui a ansiedade. Ele é a sabedoria e o poder eterno."),
    ("Sabedoria e Poesia", 3, "Provérbios 22: O Nome Bom", "Melhor é o bom nome do que grandes riquezas, e a benevolência mais que o ouro e a prata. O rico e o pobre se encontram; ambos o Senhor os fez.", "Proverbios 22:1-29", "Valorizar o caráter acima da riqueza material", "A reputação construída na justiça é mais valiosa que qualquer fortuna."),
    ("Sabedoria e Poesia", 4, "Provérbios 31: A Mulher Virtuosa", "Quem achará esposa virtuosa? Ela traz lucro e não perdas. Abre a boca com sabedoria, e na sua língua há lição de bondade. Deita e levanta à noite e de dia trabalha.", "Proverbios 31:10-31", "Reconhecer e valorizar o trabalho e o caráter da mulher virtuosa", "A mulher virtuosa é exemplo de diligência, sabedoria, bondade e temor a Deus."),
    ("Sabedoria e Poesia", 5, "Eclesiastes 1: Vaidade de Vaidades", "Vaidade de vaidades, diz o Eclesiastes, vaidade de vaidades, tudo é vaidade. Que proveito tem o homem de todo o seu trabalho? O sol nasce e se põe, e volta ao seu lugar.", "Eclesiastes 1:1-18", "Refletir sobre o sentido da vida e a vaidade das coisas terrenas", "O autor conclui que o trabalho e os prazeres são passageiros. A verdadeira satisfação está em Deus."),
    ("Sabedoria e Poesia", 6, "Eclesiastes 2: Tentativas Vãs", "Provei com o vinho, com a música, com as grandes obras, com palácios e jardins. Tudo era vaidade e aflição de espírito. Não há nada de novo sob o sol.", "Eclesiastes 2:1-26", "Entender que prazeres e conquistas não satisfazem plenamente", "O autor experimentou tudo, mas nada trouxe satisfação duradoura. O bem está em Deus."),
    ("Sabedoria e Poesia", 7, "Eclesiastes 12: Lembra do Criador", "Lembra do teu Criador na flora da tua juventude, antes que venham os maus dias e se aproximem os anos em que dirás: não tenho nele prazer algum.", "Eclesiastes 12:1-14", "Buscar a Deus desde jovem e viver com eternidade em vista", "A juventude é o tempo de buscar a Deus. A vida é vaidade sem Ele."),
    ("Sabedoria e Poesia", 8, "Cantares 1: O Amor", "Deixe-me beijar-te com o beijo da tua boca. O teu amor é melhor que o vinho. Somos negras, mas formosas. Digam-me onde apascentas o teu rebanho.", "Cantares 1:1-17", "Valorizar o amor como presente divino", "O Cantares celebra o amor humano como reflexo do amor divino. É belo e puro."),
    ("Sabedoria e Poesia", 9, "Cantares 2: O Amor Compartilhado", "Eu sou a rosa de Sarom, o lírio dos vales. Eis aqui o meu amado, eis aqui ele, saltando pelo monte. As raposas têm casas, mas o Filho do Homem não tem onde repousar.", "Cantares 2:1-17", "Reconhecer a beleza do amor compartilhado e o cuidado mútuo", "O amor é descrito com imagens da natureza: flores, montes e campos."),
    ("Sabedoria e Poesia", 10, "Cantares 8: O Amor Forte", "Põe-me como selo sobre o teu coração, como selo sobre o teu braço, porque o amor é forte como a morte. As muitas águas não podem apagar o amor.", "Cantares 8:1-14", "Compreender a força e a permanência do amor verdadeiro", "O amor descrito no Cantares é mais forte que a morte e irrevogável."),
    ("Historia de Israel", 1, "1 Reis 3: A Sabedoria de Salomão", "Deus apareceu a Salomão em sonho e ofereceu o que quisesse. Salomão pediu sabedoria para governar o povo. Deus lhe deu um coração sábio e prudente.", "1 Reis 3:1-15", "Reconhecer que a sabedoria vem de Deus", "Salomão pediu sabedoria em vez de riquezas, e Deus lhe deu tudo mais."),
    ("Historia de Israel", 2, "1 Reis 12: O Reino Dividido", "Roboão, filho de Salomão, recusou aliviar o jugo do povo. Dez tribos se revoltaram sob Jeroboão. Israel se dividiu em dois reinos: norte e sul.", "1 Reis 12:1-24", "Entender as consequências da insolência e da divisão", "A arrogância de Roboão dividiu o reino. A desobediência sempre traz consequências."),
    ("Historia de Israel", 3, "1 Reis 18-19: Elias no Carmelo", "Elias desafiou os 450 profetas de Baal no Monte Carmelo. Fogo caiu do céu sobre o sacrifício de Elias. Depois, Deus falou com Elias num murmúrio suave.", "1 Reis 18:1-19:21", "Confiar no poder de Deus mesmo contra adversários numerosos", "O confronto no Carmelo prova que o Deus de Israel é o único Deus verdadeiro."),
    ("Historia de Israel", 4, "2 Reis 2: Elias Elevado", "Elias foi elevado ao céu num redemoinho, com uma carruagem de fogo. Eliseu, seu discípulo, herdou o seu dom duplo.", "2 Reis 2:1-15", "Entender a transmissão de autoridade espiritual", "Elias não viu a morte. Eliseu herdou o poder profético em dobro."),
    ("Historia de Israel", 5, "2 Reis 17: O Exílio de Samaria", "O rei da Assíria deportou Israel para a Assíria por causa da infidelidade a Deus. Samaria caiu porque Israel pecou, serviu a outros deuses e rejeitou a aliança.", "2 Reis 17:1-41", "Reconhecer que o exílio foi consequência da desobediência", "O exílio do norte foi o juízo divino pela idolatria persistente."),
    ("Historia de Israel", 6, "Esdras 7: O Retorno", "Artaxerxes, rei da Pérsia, permitiu que Esdras voltasse a Jerusalém com autoridade para ensinar a Lei de Deus. Muitos judeus retornaram do exílio.", "Esdras 7:1-28", "Reconhecer o cumprimento da promessa de retorno", "Deus tocou o coração do rei persa para libertar o povo."),
    ("Historia de Israel", 7, "Neemias 2: Reconstrução dos Muros", "Neemias, copeiro do rei, ficou triste ao saber que os muros de Jerusalém estavam destruídos. Pediu licença ao rei e reconstruiu os muros em 52 dias.", "Neemias 2:1-20", "Entender que a restauração requer coragem e ação", "A reconstrução dos muros simboliza a restauração da identidade e proteção do povo."),
    ("Historia de Israel", 8, "Neemias 6-8: A Leitura da Lei", "Esdras leu publicamente a Lei de Deus diante de todo o povo. O povo chorou ao ouvir, mas Neemias disse: A alegria do Senhor e a vossa fortaleza.", "Neemias 8:1-12", "Reconhecer a importância da Palavra de Deus na vida do povo", "A leitura pública da Lei renovou a aliança e trouxe alegria ao povo."),
    ("Historia de Israel", 9, "Ester 4: Para Tal Tempo", "Mardoqueu disse a Ester: Quem sabe se não foste elevada a tal posição para um tempo como este? Ester arriscou a vida para salvar o povo judeu.", "Ester 4:1-17", "Reconhecer que Deus nos coloca onde precisa para cumprir Sua vontade", "Ester foi colocada no palácio para um propósito divino de salvar seu povo."),
    ("Historia de Israel", 10, "Ester 9: O Decreto de Purim", "Os judeus venceram seus inimigos na Pérsia. Ester e Mardoqueu estabeleceram a festa de Purim para lembrar a libertação. A alegria substituiu o luto.", "Ester 9:1-32", "Celebrar a libertação de Deus mesmo em tempos difíceis", "Purim celebra a vitória divina sobre os opressores."),
    ("Juizes e Ruth", 1, "Juízes 2: O Ciclo dos Juízes", "Israel pecou, entregou a Deus, Deus os vendeu a inimigos, Israel clamou, e Deus levantou um juiz para livrar. O ciclo se repetiu muitas vezes.", "Juizes 2:1-23", "Entender o padrão de pecado, juízo e misericórdia", "O ciclo dos juízes revela a paciência de Deus e a tendência humana de repetir erros."),
    ("Juizes e Ruth", 2, "Juízes 4: Débora, Juíza de Israel", "Débora, profetisa, julgava Israel sob uma palmeira. Baraque se recusou a lutar sem ela. Débora profetizou que a glória da vitória iria para uma mulher.", "Juizes 4:1-24", "Reconhecer que Deus usa mulheres poderosamente", "Débora foi líder, profetisa e juíza. Deus usa quem Ele quer, independente de gênero."),
    ("Juizes e Ruth", 3, "Juízes 6: Gideão, o Valente", "Deus chamou Gideão, o menor da família mais fraca, para libertar Israel. Gideão pediu sinais: o orvalho no véu de lã e o orvalho na eira.", "Juizes 6:1-40", "Entender que Deus usa os fracos para confundir os fortes", "Gideão duvidou, mas Deus o fortaleceu e usou seu exército pequeno."),
    ("Juizes e Ruth", 4, "Juízes 7: Os 300 Homens", "Deus reduziu o exército de Gideão de 32 mil para 300, usando o método do rio. Com tochas, cântaros e trombetas, os 300 venceram os midianitas.", "Juizes 7:1-25", "Confiar que Deus vence com pouco", "A vitória não depende do número, mas do poder de Deus."),
    ("Juizes e Ruth", 5, "Juízes 13-16: Sansão", "Sansão nasceu com força sobrenatural do Espírito do Senhor. Trabalhou incansavelmente contra os filisteus, mas foi traído por Dalila que descobriu o segredo do seu poder.", "Juizes 13:1-16:31", "Reconhecer que o poder vem de Deus e deve ser usado com sabedoria", "A força de Sansão estava no cabelo, símbolo do voto nazireu. A perda do voto foi a perda do poder."),
    ("Juizes e Ruth", 6, "Rute 1: Fidelidade de Rute", "Rute, moabita, se recusou a deixar sua sogra Noemi: “O teu povo será o meu povo, e o teu Deus será o meu Deus.” Rute seguiu Noemi a Belém.", "Rute 1:1-22", "Entender a fidelidade e a lealdade no amor", "Rute abriu mão de sua terra e seu povo para seguir a Deus e a sua sogra."),
    ("Juizes e Ruth", 7, "Rute 2: No Campo de Boaz", "Rute colhia espigas no campo de Boaz, um homem rico e parente de Noemi. Boaz mandou tratá-la bem e a protegeu.", "Rute 2:1-23", "Reconhecer a providência de Deus através de pessoas bondosas", "Deus providenciou Boaz para proteger e sustentar Ruth e Noemi."),
    ("Juizes e Ruth", 8, "Rute 3-4: O Resgate", "Boaz se ofereceu para ser o resgatador de Ruth, cumprindo a Lei do levirato. Casou-se com ela e eles foram ancestrais de Davi e de Jesus.", "Rute 3:1-4:22", "Entender que a providência de Deus se cumpre através de pessoas fiéis", "A história de Ruth e Boaz é tipo da redenção: Deus sempre provê um resgatador."),
    ("Juizes e Ruth", 9, "Juízes 17-21: Anarquia", "Na ausência de rei, Israel vivia em anarquia. Cada um fazia o que lhe parecia certo. A história do levita e sua concubina demonstra a depravação moral do período.", "Juizes 17:1-21:25", "Entender a necessidade de autoridade e de Deus como governante", "O período dos juízes termina com caos moral. Israel precisa de um rei justo."),
    ("Juizes e Ruth", 10, "Juízes 19: A Violência", "Um levita entregou sua concubina a uma multidão perversa em Gibea para salvar a si mesmo. O que aconteceu chocou todo o Israel e levou à guerra civil.", "Juizes 19:1-30", "Reconhecer o extremo da queda humana sem Deus", "A violência em Gibea é o momento mais sombrio de Juízes, mostrando a urgência de mudança."),
    ("Numeros e Deuteronomio", 1, "Números 13-14: Os Espiões", "Moisés mandou 12 espias para Canaã. 10 voltaram com medo, dizendo que os cananeus eram gigantes. Apenas Josué e Calebe confiaram em Deus. O povo chorou e queria voltar ao Egito.", "Numeros 13:1-14:45", "Entender que a desobediência e o medo geram consequências severas", "A incredulidade dos 10 espias fez todo o povo errar no deserto por 40 anos."),
    ("Numeros e Deuteronomio", 2, "Números 20: A Rocha Golpeada", "No deserto de Sinai, o povo reclamou da falta de água. Deus ordenou a Moisés que falasse com a rocha, mas Moisés golpeou a rocha duas vezes com a vara.", "Numeros 20:1-13", "Reconhecer que a desobediência tem consequências mesmo para líderes fiéis", "Moisés não entrou na Terra Prometida por causa da sua desobediência na rocha."),
    ("Numeros e Deuteronomio", 3, "Números 21-22: A Serpente e Balaão", "No deserto, serpentes venenosas atacaram Israel. Deus mandou Moisés fazer uma serpente de bronze; quem a olhasse vivia. Depois, Balaão foi contratado para amaldiçoar Israel.", "Numeros 21:1-22:41", "Entender o julgamento e a proteção divina simultâneas", "A serpente de bronze é tipo de Cristo levantado. Balaão não pôde amaldiçoar o que Deus abençoou."),
    ("Numeros e Deuteronomio", 4, "Números 32: Gade e Rúben", "As tribos de Gade e Rúben pediram terra além do Jordão por terem muitos rebanhos. Moisés concordou com a condição de ajudar a conquistar a terra.", "Numeros 32:1-42", "Entender que privilégios trazem responsabilidades", "Gade e Rúben receberam terra, mas tiveram que lutar primeiro com os outros."),
    ("Numeros e Deuteronomio", 5, "Deuteronômio 6: O Shema", "Ouve, Israel: o Senhor é o nosso Deus, o Senhor é um só. Amarás ao Senhor de todo o teu coração, de toda a tua alma e de todas as tuas forças.", "Deuteronomio 6:1-9", "Entender o mandamento central da fé israelita", "O Shema é a declaração monoteísta mais importante de Israel."),
    ("Numeros e Deuteronomio", 6, "Deuteronômio 8: Lembra do Senhor", "Lembra‑te de todo o caminho por onde o Senhor te conduziu no deserto, para te humilhar e para provares se guardas ou não os mandamentos.", "Deuteronomio 8:1-20", "Reconhecer que tudo vem de Deus e que devemos obedecer", "Deus humilhou Israel no deserto para ensinar que não só de pão vive o homem."),
    ("Numeros e Deuteronomio", 7, "Deuteronômio 28: Bênçãos e Pragas", "Se ouvires a voz do Senhor, serás abençoado em tudo. Mas se não ouvires, virão pragas, fome, peste e exílio. A desobediência traz maldição.", "Deuteronomio 28:1-68", "Entender as consequências da obediência e da desobediência", "A aliança traz bênçãos na obediência e pragas na desobediência."),
    ("Numeros e Deuteronomio", 8, "Deuteronômio 30: Vida e Morte", "Propus diante de ti a vida e a morte, a bênção e a maldição. Escolhe a vida para que vivas tu e a tua descendência, amando o Senhor teu Deus.", "Deuteronomio 30:1-20", "Fazer a escolha pela vida em Deus", "Deus apresenta a escolha: vida com Deus ou morte sem Ele."),
    ("Numeros e Deuteronomio", 9, "Deuteronômio 34: A Morte de Moisés", "Moisés subiu ao monte Nebo e viu toda a terra prometida. Morreu ali aos 120 anos, ainda com a vista boa e a força inteira. Nenhum profeta se levantou como ele.", "Deuteronomio 34:1-12", "Honrar a liderança de Moisés e a soberania de Deus", "Moisés viu a terra mas não entrou. Deus cumpriu Sua palavra."),
    ("Numeros e Deuteronomio", 10, "Deuteronômio 1-2: Relembrando", "Moisés relembrando o caminho de Israel: a saída do Egito, a Lei no Sinai, as provas no deserto e a proximidade da Terra Prometida.", "Deuteronomio 1:1-2:1", "Reconhecer a fidelidade de Deus ao longo da jornada", "O Deuteronômio e o discurso final de Moisés, resumindo tudo que Deus fez."),
    ("Isaias e Jeremias Profecias", 1, "Isaías 1: A Acusação", "O Senhor acusa Israel: reconheci filhos, mas me rebelaram. Não há integridade, apenas feridas. Seus sacrifícios me saciaram. Lavai‑vos, purificai‑vos.", "Isaias 1:1-20", "Entender a exigência de justiça e não apenas de rituais", "Deus rejeita a religiosidade vazia sem justiça e misericórdia."),
    ("Isaias e Jeremias Profecias", 2, "Isaías 6: O Chamado de Isaías", "Isaías viu o Senhor assentado no trono, com as barbas enchendo o templo. Seráfins clamavam: Santo, Santo, Santo. Isaías disse: Ai de mim! Um seráfim tocou seus lábios com brasa.", "Isaias 6:1-13", "Reconhecer a santidade de Deus e a reação do homem pecador", "A visão da santidade de Deus leva à consciência do pecado e ao chamado profético."),
    ("Isaias e Jeremias Profecias", 3, "Isaías 9: O Príncipe da Paz", "Para nós nasceu uma criança, para nós foi dado um filho; e o principado estará sobre os seus ombros. Conselheiro maravilhoso, Deus fortíssimo, Pai eterno, Príncipe da Paz.", "Isaias 9:1-7", "Reconhecer Jesus como o Messias prometido", "Isaías profetizou a vinda de um governante perfeito cujo reinado seria eterno."),
    ("Isaias e Jeremias Profecias", 4, "Isaías 40: Consolo", "Consolai, consolai o meu povo, diz o vosso Deus. Fala ao coração de Jerusalém, porque a sua servidão já acabou. Todo ser humano é como a erva.", "Isaias 40:1-31", "Receber o consolo de Deus na tribulação", "Deus consola Seu povo e renova as forças dos que nele esperam."),
    ("Isaias e Jeremias Profecias", 5, "Isaías 53: O Servo Sofredor", "Ele foi desprezado e rejeitado pelos homens, homem de doenças. Foi traspassado pelas nossas transgressões, moído pelas nossas iniquidades. Pela sua chaga fomos sarados.", "Isaias 53:1-12", "Reconhecer Jesus como o Servo Sofredor profetizado", "A profecia mais clara sobre a morte expiatória de Jesus, escrita 700 anos antes da cruz."),
    ("Isaias e Jeremias Profecias", 6, "Isaías 61: Boas Novas", "O espírito do Senhor está sobre mim, porque o Senhor me ungiu para pregar boas novas aos pobres, para curar os quebrantados de coração, proclamar liberdade aos cativos.", "Isaias 61:1-3", "Reconhecer que Jesus cumpriu esta profecia", "Jesus leu esta passagem na sinagoga e disse: Hoje se cumpriu."),
    ("Isaias e Jeremias Profecias", 7, "Jeremias 1: O Chamado", "Antes de te formar no ventre, eu te conheci e te consagrei. Não digas: sou menino, porque onde eu te enviar, irás, e o que eu te mandar, dirás.", "Jeremias 1:1-19", "Entender que Deus chama desde antes do nascimento", "Jeremias foi chamado jovem, mas Deus o capacitou."),
    ("Isaias e Jeremias Profecias", 8, "Jeremias 29: Planos de Bem", "Porque eu bem sei os pensamentos que tenho a vosso respeito, pensamentos de paz e não de mal, para vos dar o fim que esperais. Clamai a mim, e responderei.", "Jeremias 29:11-14", "Confiar nos planos de Deus mesmo na dificuldade", "Deus falou ao povo exilado na Babilônia: Ele tinha planos de bem."),
    ("Isaias e Jeremias Profecias", 9, "Jeremias 31: A Nova Aliança", "Farei uma aliança nova com Israel. Porei a minha Lei no seu interior e a escreverei nos seus corações. Perdoarei as iniquidades deles.", "Jeremias 31:31-34", "Entender o fundamento da nova aliança em Cristo", "A nova aliança é interior e pessoal, não baseada em tábuas de pedra."),
    ("Isaias e Jeremias Profecias", 10, "Lamentações 3: Misericórdias", "As misericórdias do Senhor não se esgotam; são novas a cada manhã. Grande é a fidelidade do Senhor. O Senhor não rejeita para sempre.", "Lamentacoes 3:22-33", "Renovar a esperança nas misericórdias renovadas de Deus", "Mesmo na destruição de Jerusalém, há esperança nas misericórdias de Deus."),
    ("Criancas: Historias do AT", 1, "Criação: Deus fez tudo", "Deus criou o céu e a terra, os animais, as estrelas e você também! Tudo que é bonito veio de Deus. Ele é poderoso e bom.", "Genesis 1:1-31", "Amar a Deus como criador de todas as coisas", "Deus fez tudo com amor, inclusive você!"),
    ("Criancas: Historias do AT", 2, "Noé e a Arca", "Deus mandou Noé construir uma arca enorme. Noé obedeceu e levou sua família e os animais. Depois veio o dilúvio, mas Deus protegeu a todos.", "Genesis 6:1-9:17", "Obedecer a Deus mesmo quando é difícil", "Noé confiou em Deus e foi salvo junto com sua família."),
    ("Criancas: Historias do AT", 3, "Abraão Viajou", "Deus disse a Abraão: Vai-te da tua terra! Abraão obedeceu e foi para uma terra desconhecida. Deus prometeu fazer dele um grande povo.", "Genesis 12:1-9", "Confiar em Deus quando não sabemos o caminho", "Abraão seguiu Deus sem saber para onde ia. Essa é fé!"),
    ("Criancas: Historias do AT", 4, "José Sonhou", "José era o filho favorito do pai Jacó. Seus irmãos tinham inveja porque José contou seus sonhos de que seriam seus servos. Isso fez os irmãos ficarem com raiva.", "Genesis 37:1-36", "Não ter inveja e perdoar", "Mesmo com a injustiça, Deus estava no controle."),
    ("Criancas: Historias do AT", 5, "José no Palácio", "No Egito, José foi preso injustamente, mas Deus o ajudou. Ele interpretou sonhos do faraó e foi tornado governador do Egito inteiro.", "Genesis 41:1-46", "Deus está no controle mesmo quando as coisas parecem ruins", "Deus transformou a prisão em governança."),
    ("Criancas: Historias do AT", 6, "José Abraçou", "José revelou sua identidade aos irmãos: Eu sou José! Chorou e os abraçou. Disse: Vocês quiseram me fazer mal, mas Deus transformou em bem.", "Genesis 45:1-15", "Perdoar e ver a mão de Deus nas situações ruins", "O perdão de José é um dos mais lindos exemplos da Bíblia."),
    ("Criancas: Historias do AT", 7, "José Perdoou", "Quando o pai Jacó morreu, os irmãos tiveram medo. José disse: Não tenham medo, eu sou de Deus para cuidar de vocês. Perdoou‑os totalmente.", "Genesis 50:15-21", "O perdão total e o amor que transforma", "José perdoou de verdade, sem guardar rancor."),
    ("Criancas: Historias do AT", 8, "Moisés Bebê Salvo", "Uma mãe hebreia escondeu o bebê Moisés num cesto no Nilo. A filha do faraó o encontrou e criou‑o no palácio. Deus cuidou de Moisés.", "Exodo 2:1-10", "Deus protege seus desde o nascimento", "A mãe de Moisés confiou em Deus e Ele cuidou do bebê."),
    ("Criancas: Historias do AT", 9, "Mar Vermelho", "Moisés levou Israel pelo deserto. O faraó mandou exército atrás deles. Moisés ergueu a vara e o Mar Vermelho se abriu! Israel passou em seco.", "Exodo 14:1-31", "Deus salva o Seu povo dos perigos", "O Mar Vermelho é o maior milagre de salvação do AT!"),
    ("Criancas: Historias do AT", 10, "Dez Mandamentos", "Deus deu dez regras para o povo no monte Sinai. A primeira é: Ame a Deus acima de tudo. As outras ensinam a amar o próximo.", "Exodo 20:1-17", "Obedecer a Deus e amar ao próximo", "Os mandamentos são as regras de Deus para nosso bem."),
    ("Criancas: Historias de Jesus", 1, "O Nascimento de Jesus", "Jesus nasceu numa manjedoura em Belém. Anjos anunciaram o nascimento aos pastores. Reis vieram do oriente para adorá‑lo. O mundo celebrou o nascimento do Salvador.", "Mateus 1:18-2:12", "Celebrar o nascimento de Jesus como presente de Deus", "Jesus veio ao mundo para salvar todos nós!"),
    ("Criancas: Historias de Jesus", 2, "O Batismo de Jesus", "Jesus foi batizado por João Batista no Rio Jordão. Ao subir das águas, o céu se abriu e o Espírito Santo desceu como pomba. Uma voz do céu disse: Este é o Meu Filho amado.", "Mateus 3:13-17", "Entender que Jesus é o Filho de Deus", "Deus confirmou que Jesus é o Seu Filho amado."),
    ("Criancas: Historias de Jesus", 3, "A Tentação de Jesus", "Jesus foi ao deserto e o diabo tentou Ele. Jesus resistiu a cada tentação usando a Palavra de Deus. O diabo foi embora.", "Mateus 4:1-11", "Usar a Palavra de Deus para resistir ao mal", "Jesus nos mostra que podemos vencer as tentações."),
    ("Criancas: Historias de Jesus", 4, "O Sermão da Montanha", "Jesus ensinou as pessoas numa montanha. Disse: Bem-aventurados os mansos, os que choram, os que têm fome de justiça. Vocês são a luz do mundo.", "Mateus 5:1-48", "Aprender os ensinamentos de Jesus", "Jesus ensina a viver com amor, humildade e justiça."),
    ("Criancas: Historias de Jesus", 5, "Jesus Cura", "Jesus andou por toda parte curando enfermos. Curou cegos, coxos e até levantou mortos. Ele tinha compaixão de todos.", "Mateus 9:1-38; Lucas 4:40", "Amar e cuidar dos que precisam", "Jesus cura porque ama cada pessoa."),
    ("Criancas: Historias de Jesus", 6, "As Parábolas", "Jesus contou histórias para ensinar: o Semeador, a Ovelha Perdida, o Filho Pródigo. Cada parábola ensina algo importante sobre o Reino de Deus.", "Mateus 13:1-58", "Prestar atenção nos ensinamentos de Jesus", "As parábolas são histórias com lições profundas."),
    ("Criancas: Historias de Jesus", 7, "Pão e Peixes", "Jesus alimentou 5 mil pessoas com 5 pães e 2 peixes. Ele multiplicou a comida. Todos ficaram satisfeitos e sobrou!", "Mateus 14:13-21", "Confiar que Jesus supre todas as nossas necessidades", "Com Jesus, o pouco se torna muito!"),
    ("Criancas: Historias de Jesus", 8, "Jesus Ressuscitou", "Jesus morreu na cruz para nos salvar. No terceiro dia, Ele ressuscitou! A tumba ficou vazia. Jesus vive e isso muda tudo!", "Mateus 28:1-20", "Celebrar a ressurreição de Jesus e ter esperança", "Jesus venceu a morte! Isso é a melhor notícia do mundo!"),
    ("Criancas: Historias de Jesus", 9, "Pastores Adoraram", "Pastores estavam no campo quando anjos apareceram e disseram: Nasceu em Belém o Salvador! Os pastores foram adorar o bebê Jesus.", "Lucas 2:8-20", "Adorar a Jesus com alegria", "Os pastores foram os primeiros a adorar Jesus."),
    ("Criancas: Historias de Jesus", 10, "O Filho Pródigo", "Um filho pediu sua parte e foi embora. Gastou tudo e ficou com fome. Voltou pedindo perdão. O pai o recebeu com abraços e festa!", "Lucas 15:11-32", "Que Deus sempre nos recebe de volta", "Não importa o que fizemos, Deus nos ama e nos recebe!"),
    ("Adolescentes: Quem e Jesus?", 1, "João 1: Verbo Feito Carne", "No princípio era o Verbo, e o Verbo estava com Deus, e o Verbo era Deus. Tudo foi feito por Ele. E o Verbo se fez carne e habitou entre nós.", "João 1:1-18", "Entender que Jesus é eterno e divino", "Jesus não começou a existir no nascimento. Ele é o Verbo eterno."),
    ("Adolescentes: Quem e Jesus?", 2, "João 3: Nascer de Novo", "Jesus disse a Nicodemos: É necessário nascer de novo para ver o Reino de Deus. Quem crer no Filho não perece, mas tem a vida eterna.", "João 3:1-36", "Entender a necessidade do novo nascimento espiritual", "Nascemos de novo pelo Espírito Santo."),
    ("Adolescentes: Quem e Jesus?", 3, "João 4: A Samaritana", "Jesus falou com uma mulher samaritana no poço de Jacó. Ela tinha 5 maridos. Jesus revelou que era o Messias. Ela correu e contou tudo.", "João 4:1-42", "Jesus não rejeita ninguém", "Jesus quebrou barreiras de cultura e gênero para falar com ela."),
    ("Adolescentes: Quem e Jesus?", 4, "Marcos 1: O Chamado", "Jesus chamou seus primeiros discípulos: Venham e segui-me. Eles deixaram tudo e o seguiram. Jesus tinha autoridade diferente dos escribas.", "Marcos 1:1-20", "Entender o que significa seguir a Jesus", "Seguir Jesus e deixar tudo e ir com Ele."),
    ("Adolescentes: Quem e Jesus?", 5, "Marcos 4: A Tempestade", "Jesus dormia no barco quando uma tempestade surgiu. Os discípulos o acordaram. Jesus disse: Acalma‑te! E o mar se acalmou.", "Marcos 4:35-41", "Jesus tem poder sobre tudo", "Mesmo na tempestade, Jesus está no controle."),
    ("Adolescentes: Quem e Jesus?", 6, "Marcos 8: O Cego", "Jesus colocou lama nos olhos de um cego e perguntou: Que vês? O homem disse: Vejo pessoas como árvores. Jesus tocou novamente e ele via perfeitamente.", "Marcos 8:22-26", "Jesus cura completamente", "Jesus não faz nada pela metade. Ele quer curar totalmente."),
    ("Adolescentes: Quem e Jesus?", 7, "Lucas 9: Discipulado", "Jesus disse: Se alguém quiser vir após mim, negue a si mesmo, tome a sua cruz e siga-me. De que aproveita ganhar o mundo e perder a si mesmo?", "Lucas 9:23-25", "Entender o custo e a alegria de seguir Jesus", "Seguir Jesus exige dedicação total, mas traz vida eterna."),
    ("Adolescentes: Quem e Jesus?", 8, "Lucas 19: Zaqueu", "Zaqueu era chefe dos publicanos e era rico. Subiu numa árvore para ver Jesus. Jesus disse: Zaqueu, desce, porque hoje preciso ficar em tua casa.", "Lucas 19:1-10", "Jesus vem até nós onde estamos", "Não importa quem você é, Jesus quer estar com você."),
    ("Adolescentes: Quem e Jesus?", 9, "Mateus 28: A Ressurreição", "Jesus ressuscitou! Os anjos disseram: Ele não está aqui, pois ressuscitou. Jesus apareceu aos discípulos e disse: Toda autoridade me é dada. Vão e façam discípulos.", "Mateus 28:1-20", "A Ressurreição e a base da fé cristã", "Jesus venceu a morte e tem toda autoridade."),
    ("Adolescentes: Quem e Jesus?", 10, "Apocalipse 1: Jesus Glorificado", "João viu Jesus glorificado: olhos como chamas de fogo, voz como muitas águas. Jesus disse: Eu sou o Alfa e o Ômega, o que era, que é e que há de vir.", "Apocalipse 1:9-20", "Jesus é glorioso e poderoso", "Jesus é o mesmo de ontem, hoje e sempre."),
    ("Adolescentes: Vida Crista", 1, "Efésios 1: Identidade em Cristo", "Deus nos abençoou com todas as bênçãos espirituais. Nos escolheu antes da fundação do mundo, predestinou para filhos adotivos. Somos aceitos no Amado.", "Efesios 1:3-14", "Conhecer sua identidade como filho amado de Deus", "Você não é acidente. Deus te escolheu antes de tudo."),
    ("Adolescentes: Vida Crista", 2, "Efésios 6: A Armadura de Deus", "Vesti a armadura de Deus: cinto da verdade, couraça da justiça, escudo da fé, capacete da salvação, espada do Espírito e oração.", "Efesios 6:10-20", "Vestir‑se espiritualmente todos os dias", "A guerra espiritual é real, mas Deus fornece toda armadura."),
    ("Adolescentes: Vida Crista", 3, "Filipenses 4: Alegria", "Alegrai‑vos sempre no Senhor. Novamente digo: alegrai‑vos. Não vos atristeis por nada. O Deus da paz estará convosco.", "Filipenses 4:4-13", "Cultivar alegria que não depende de circunstâncias", "A alegria cristã é profunda, mesmo nas dificuldades."),
    ("Adolescentes: Vida Crista", 4, "Colossenses 2: Completos em Cristo", "Em Cristo habita toda a plenitude da divindade. Vós estáis completos nele. Não deixem que ninguém os engane com filosofias vazias.", "Colossenses 2:9-15", "Viver na certeza de que Cristo nos completa", "Não precisamos de nada além de Cristo para estar completos."),
    ("Adolescentes: Vida Crista", 5, "Tiago 1: Tribulações", "Considerai puro gozo quando entrardes em provações de muitas sortes, porque a fé provada produz perseverança. Se falta sabedoria, peça a Deus.", "Tiago 1:2-12", "Encontrar alegria nas dificuldades", "As provações fortalecem a fé e produzem maturidade."),
    ("Adolescentes: Vida Crista", 6, "Tiago 2: Fé e Obras", "Se alguém diz que tem fé e não tem obras, que lhe aproveita? A fé sem obras é morta. Mostra‑me a tua fé pelas tuas obras.", "Tiago 2:14-26", "Viver uma fé que se demonstra em ações", "Fé genuína se manifesta em obras."),
    ("Adolescentes: Vida Crista", 7, "1 Coríntios 13: O Amor", "Sem amor, nada temos. O amor é paciente, bondoso, não busca seus interesses, não se irrita. A fé, a esperança e o amor permanecem, mas o maior é o amor.", "1 Corintios 13:1-13", "Amar como Deus ama", "O amor é o mais excelente caminho."),
    ("Adolescentes: Vida Crista", 8, "1 Pedro 2: Pedras Vivas", "Vós sois pedras vivas, edificados espiritualmente. Cristo é a pedra angular. Somos uma casa sacerdotal espiritual para oferecer sacrifícios espirituais.", "1 Pedro 2:1-10", "Ser parte viva da igreja de Cristo", "Cada crente é uma pedra viva na casa de Deus."),
    ("Adolescentes: Vida Crista", 9, "Romanos 8: Sem Condenação", "Não há condenação para os que estão em Cristo Jesus. Nada pode nos separar do amor de Deus. O Espírito nos ajuda em nossas fraquezas.", "Romanos 8:1-39", "Viver livres da culpa e da condenação", "Em Cristo, não há condenação!"),
    ("Adolescentes: Vida Crista", 10, "2 Timóteo 4: Perseverança", "Combate o bom combate da fé. Persiga a justiça. Fui derramado como oferta de libação. Despacho já está feito. Guarda a coroa da justiça.", "2 Timoteo 4:1-8", "Ser fiel até o fim", "Paulo encoraja a perseverança até a volta de Cristo."),
    ("Teologia Sistematica", 1, "Gênesis 1-2: Criação", "Deus criou tudo por Sua palavra. O homem foi feito à Sua imagem e semelhança, com dignidade e responsabilidade sobre a criação.", "Genesis 1:1-2:25", "Compreender os fundamentos da doutrina da criação", "Deus é o Criador soberano. O homem tem dignidade por ser a imagem de Deus."),
    ("Teologia Sistematica", 2, "Gênesis 3: A Queda", "Adão e Eva desobedeceram a Deus e o pecado entrou no mundo. A consequência foi a morte espiritual, a expulsão do Éden e a maldição sobre a terra.", "Genesis 3:1-24", "Entender a doutrina do pecado original", "A Queda corrompeu toda a humanidade. Todos precisamos de redenção."),
    ("Teologia Sistematica", 3, "Romanos 3-4: Justificação", "Todos pecaram e faltam da glória de Deus. Mas somos justificados gratuitamente pela graça, mediante a redenção em Cristo Jesus. A fé de Abraão e o modelo.", "Romanos 3:21-4:25", "Compreender a doutrina da justificação pela fé", "A justificação é um ato gratuito de Deus que nos declara justos pela fé."),
    ("Teologia Sistematica", 4, "Romanos 5: Paz com Deus", "Sendo justificados pela fé, temos paz com Deus. A graça de Deus abunda onde o pecado aumentou. O amor de Deus foi derramado em nossos corações.", "Romanos 5:1-11", "Experimentar a paz e o acesso à graça", "A justificação traz paz com Deus e acesso à Sua graça."),
    ("Teologia Sistematica", 5, "Romanos 6: Libertação do Pecado", "Devemos viver como mortos para o pecado. Fomos batizados com Cristo na morte e ressurreição. O pecado não terá domínio sobre nós, pois estamos debaixo da graça.", "Romanos 6:1-23", "Entender que a graça liberta, não autoriza pecar", "Somos novas criaturas livres do domínio do pecado."),
    ("Teologia Sistematica", 6, "Romanos 8: Glorificação", "Não há condenação para quem está em Cristo. O Espírito nos vivifica. Nada pode nos separar do amor de Deus. Todos os que foram predestinados serão chamados e justificados.", "Romanos 8:1-39", "Compreender a glorificação como etapa final da salvação", "Deus completa Sua obra em nós. A glória eterna é certa."),
    ("Teologia Sistematica", 7, "Efésios 1: Eleição", "Deus nos escolheu em Cristo antes da fundação do mundo, predestinando‑nos para adoção. Tudo segundo o propósito da Sua vontade.", "Efesios 1:3-14", "Entender a doutrina da eleição divina", "Deus é soberano na Sua escolha, por amor e para Sua glória."),
    ("Teologia Sistematica", 8, "Hebreus 1-2: Cristologia", "Cristo é a imagem do Deus invisível, superior a todos os anjos. Por Ele foram criadas todas as coisas. Tornou‑se um pouco menor que os anjos para sofrer a morte.", "Hebreus 1:1-2:18", "Compreender a natureza divina e humana de Cristo", "Cristo é plenamente Deus e plenamente homem. A encarnação é o mistério central da fé."),
    ("Teologia Sistematica", 9, "1 Coríntios 15: Ressurreição", "Se Cristo não ressuscitou, a fé é vã. Mas Cristo ressuscitou e é a primícia dos que dormem. Seremos transformados em corpos gloriosos.", "1 Corintios 15:1-58", "Firmar a fé na ressurreição corporal", "A ressurreição de Cristo é o fundamento da fé cristã."),
    ("Teologia Sistematica", 10, "Apocalipse 21: Escatologia", "Vi os novos céus e a nova terra. A Nova Jerusalém desce do céu. Não haverá mais lágrimas, nem morte, nem dor. O Senhor será o seu Deus, e eles serão o Seu povo.", "Apocalipse 21:1-22:21", "Esperar a consumação de todas as coisas", "A esperança final é a nova criação, onde Deus habita com o Seu povo."),
]
